/**
 * Forces on a hex: column composition, split / merge / garrison / withdraw, and
 * the spy-drone launcher with a live detection-risk read along the planned
 * route (GDD §5.1, §3.4).
 *
 * The risk number is computed with the same pure functions the world tick uses
 * (`isRiskyHex` + `detectionChance`), so what the player is shown is exactly the
 * model that will be rolled against.
 */
import { BATTLE, DRONES, MAP } from '../../config';
import { UNITS } from '../../config/units';
import type { Army, ArmyId, GameState, HexId, UnitId, UnitType } from '../../game/types';
import { findPath, hexDistanceId, parseHexId } from '../../game/hex';
import { isHexOpen } from '../../game/world/generate';
import { aliveDronesOf, detectionChance, isRiskyHex } from '../../game/world/drones';
import { areHostile, moveCooldownRemaining } from '../../game/world/movement';
import {
  badge,
  button,
  countdown,
  emptyState,
  ICONS,
  iconButton,
  meter,
  openModal,
  sectionHeader,
  statRow,
  unitChip,
  unitSilhouette,
} from '../components';
import { el, fmtDuration, fmtNum, haptic, svg as svgEl } from '../dom';
import {
  commit,
  compositionStrip,
  factionKey,
  fortTag,
  myFaction,
  type PanelCtx,
} from './intelPanel';

/** How the sheet hands control back to the map screen. */
export interface ArmyHooks {
  /** Put this column into the order flow (map screen picks the destination). */
  onOrderArmy?(armyId: ArmyId): void;
  onFocusHex?(hexId: HexId): void;
}

/** Longest candidate list shown in the drone destination picker (UI only). */
const MAX_DRONE_TARGETS = 12;

function compositionOf(army: Army): Partial<Record<UnitType, number>> {
  const out: Partial<Record<UnitType, number>> = {};
  for (const u of army.units) out[u.type] = (out[u.type] ?? 0) + 1;
  return out;
}

function armyHp(army: Army): { hp: number; max: number } {
  let hp = 0;
  let max = 0;
  for (const u of army.units) {
    hp += u.hp;
    max += UNITS[u.type].hp;
  }
  return { hp, max };
}

export function armiesOn(state: GameState, hexId: HexId): Army[] {
  return Object.values(state.armies)
    .filter((a) => a.hexId === hexId)
    .sort((a, b) => (a.id < b.id ? -1 : 1));
}

// ─────────────────────────────────────────────────────────────────────────────
// Friendly columns
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Every column of yours standing on this hex, with unit-level selection driving
 * split and garrison, plus merge and halt.
 */
export function armiesPanel(
  state: GameState,
  hexId: HexId,
  ctx: PanelCtx,
  hooks: ArmyHooks = {},
): HTMLElement {
  const root = el('div', { class: 'forces' });
  const mine = armiesOn(state, hexId).filter((a) => a.ownerId === state.meId);
  const hex = state.world.hexes[hexId];

  root.appendChild(
    sectionHeader('YOUR COLUMNS', badge(`${mine.length} ON SITE`, mine.length > 0 ? 'ok' : 'default')),
  );

  if (mine.length === 0) {
    root.appendChild(emptyState('⬡', 'no column of yours is standing here'));
    return root;
  }

  for (const army of mine) {
    root.appendChild(armyCard(state, army, mine, hexId, ctx, hooks, hex?.ownerId === state.meId));
  }
  return root;
}

function armyCard(
  state: GameState,
  army: Army,
  siblings: Army[],
  hexId: HexId,
  ctx: PanelCtx,
  hooks: ArmyHooks,
  ownsHex: boolean,
): HTMLElement {
  const moving = army.arrivesAt !== undefined || army.path.length > 0;
  const cooling = moving ? 0 : moveCooldownRemaining(army, ctx.now());
  const card = el('div', {
    class: `army-card${moving ? ' army-card--moving' : ''}${cooling > 0 ? ' army-card--cooling' : ''}`,
  });

  const { hp, max } = armyHp(army);
  const bar = meter(hp, Math.max(1, max), { height: 5, autoTint: true });

  const head = el(
    'div',
    { class: 'army-card__head' },
    el(
      'div',
      { class: 'grow' },
      el('div', { class: 'army-card__name display', text: army.name }),
      el('div', {
        class: 'army-card__sub mono',
        text: `${army.units.length}/${BATTLE.armyCap} CHASSIS · ${hp}/${max} HP`,
      }),
    ),
    moving
      ? badge('IN TRANSIT', 'gold')
      : cooling > 0
        ? badge('REGROUPING', 'violet')
        : badge('HOLDING', 'ok'),
  );
  card.appendChild(head);
  card.appendChild(bar.el);

  if (army.siege) {
    const cd = countdown(army.siege.readyAt, { getNow: ctx.now, prefix: 'BREACH IN' });
    ctx.onDispose(() => cd.stop());
    card.appendChild(el('div', { class: 'army-card__siege' }, el('span', { text: 'SIEGE LINE SET' }), cd.el));
  } else if (moving && army.path.length > 0) {
    const last = army.path[army.path.length - 1];
    const cd = countdown(last.arrivesAt, { getNow: ctx.now, prefix: 'ARRIVES' });
    ctx.onDispose(() => cd.stop());
    card.appendChild(
      el('div', { class: 'army-card__transit' }, el('span', { class: 'mono', text: `→ ${last.hexId}` }), cd.el),
    );
  }

  // ── unit selection ────────────────────────────────────────────────────────
  const selected = new Set<UnitId>();
  const grid = el('div', { class: 'army-card__units' });

  const syncButtons = (): void => {
    const n = selected.size;
    splitBtn.disabled = moving || n === 0 || n >= army.units.length;
    garrisonBtn.disabled = moving || n === 0 || !ownsHex;
    countNode.textContent = n > 0 ? `${n} SELECTED` : 'TAP CHASSIS TO SELECT';
  };

  for (const unit of army.units) {
    const chip = unitChip(unit.type, {
      small: true,
      hp: unit.hp,
      maxHp: UNITS[unit.type].hp,
      onClick: () => {
        if (selected.has(unit.id)) selected.delete(unit.id);
        else selected.add(unit.id);
        chip.classList.toggle('uchip--sel', selected.has(unit.id));
        haptic(6);
        syncButtons();
      },
    });
    grid.appendChild(chip);
  }
  card.appendChild(grid);

  const countNode = el('div', { class: 'army-card__count mono', text: 'TAP CHASSIS TO SELECT' });
  card.appendChild(countNode);

  // ── controls ──────────────────────────────────────────────────────────────
  const splitBtn = button('SPLIT', {
    variant: 'ghost',
    small: true,
    onClick: () => {
      void (async () => {
        if (
          await commit(
            ctx.backend.splitArmy(army.id, [...selected]),
            'DETACHMENT FORMED',
            `${selected.size} chassis peeled off ${army.name}`,
          )
        ) {
          ctx.refresh();
        }
      })();
    },
  });

  const garrisonBtn = button('GARRISON', {
    variant: 'ghost',
    small: true,
    onClick: () => {
      void (async () => {
        if (
          await commit(
            ctx.backend.garrisonUnits(army.id, [...selected]),
            'STOOD DOWN TO RESERVE',
            `${selected.size} chassis bedded in at ${hexId}`,
          )
        ) {
          ctx.refresh();
        }
      })();
    },
  });

  const orderBtn = button(moving ? 'RE-ROUTE' : 'ORDER MARCH', {
    variant: 'primary',
    small: true,
    disabled: cooling > 0,
    onClick: () => hooks.onOrderArmy?.(army.id),
  });

  // The regroup plate sits where the transit / siege readout would, so the
  // column's current state is always the same line of the card.
  if (cooling > 0 && army.moveReadyAt !== undefined) {
    const cd = countdown(army.moveReadyAt, {
      getNow: ctx.now,
      prefix: 'READY IN',
      doneText: 'READY',
      onDone: () => {
        orderBtn.disabled = false;
        card.classList.remove('army-card--cooling');
      },
    });
    ctx.onDispose(() => cd.stop());
    card.insertBefore(
      el(
        'div',
        { class: 'army-card__regroup' },
        el('span', { text: 'DUG IN · REGROUPING' }),
        cd.el,
      ),
      grid,
    );
  }

  const controls = el('div', { class: 'army-card__acts' }, orderBtn, splitBtn, garrisonBtn);

  if (moving) {
    controls.appendChild(
      button('HALT', {
        variant: 'danger',
        small: true,
        onClick: () => {
          void (async () => {
            if (await commit(ctx.backend.haltArmy(army.id), 'COLUMN HALTED')) ctx.refresh();
          })();
        },
      }),
    );
  }

  const others = siblings.filter((a) => a.id !== army.id);
  if (others.length > 0 && !moving) {
    controls.appendChild(
      button('MERGE', {
        variant: 'quiet',
        small: true,
        onClick: () => mergePicker(army, others, ctx),
      }),
    );
  }

  card.appendChild(controls);
  syncButtons();
  return card;
}

function mergePicker(into: Army, others: Army[], ctx: PanelCtx): void {
  const body = el('div', { class: 'col' });
  body.appendChild(
    el('p', {
      class: 'dim',
      text: `Fold another column into ${into.name}. The combined force may not exceed ${BATTLE.armyCap} chassis.`,
    }),
  );
  const handle = openModal({
    title: 'MERGE COLUMNS',
    body,
    accent: 'var(--teal)',
    actions: [{ label: 'CANCEL', variant: 'ghost' }],
  });
  for (const other of others) {
    body.appendChild(
      button(other.name, {
        variant: 'ghost',
        wide: true,
        sub: `${other.units.length} CHASSIS`,
        onClick: () => {
          handle.close();
          void (async () => {
            if (await commit(ctx.backend.mergeArmies(into.id, other.id), 'COLUMNS MERGED')) ctx.refresh();
          })();
        },
      }),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Hostile / allied columns present
// ─────────────────────────────────────────────────────────────────────────────

/** Anything standing here that is not yours — read-only. */
export function foreignArmiesPanel(state: GameState, hexId: HexId): HTMLElement | null {
  const foreign = armiesOn(state, hexId).filter(
    (a) => a.ownerId !== state.meId && a.units.length > 0,
  );
  if (foreign.length === 0) return null;

  const root = el('div', { class: 'forces' });
  root.appendChild(sectionHeader('COLUMNS ON SITE'));
  for (const army of foreign) {
    const owner = state.players[army.ownerId];
    const guild = state.guilds[army.guildId];
    const hostile = areHostile(state, army.ownerId, state.meId);
    const row = el(
      'div',
      { class: `foreign${hostile ? ' foreign--hostile' : ''}` },
      el(
        'div',
        { class: 'row' },
        el('span', { class: 'foreign__name display truncate grow', text: owner?.name ?? 'UNKNOWN' }),
        badge(guild ? `[${guild.tag}]` : 'FREELANCE', hostile ? 'hot' : 'ok'),
      ),
      el('div', { class: 'foreign__sub mono', text: `${army.name} · ${army.units.length} CHASSIS` }),
      compositionStrip(compositionOf(army)),
    );
    root.appendChild(row);
  }
  return root;
}

// ─────────────────────────────────────────────────────────────────────────────
// Reserve garrison
// ─────────────────────────────────────────────────────────────────────────────

/** Reserve units bedded in on this hex, with a withdraw stepper per chassis. */
export function garrisonPanel(state: GameState, hexId: HexId, ctx: PanelCtx): HTMLElement {
  const root = el('div', { class: 'garrison' });
  const hex = state.world.hexes[hexId];
  const reserves = hex ? hex.reserves : {};
  const entries = (Object.entries(reserves) as [UnitType, number][]).filter(([, n]) => n > 0);
  const total = entries.reduce((n, [, c]) => n + c, 0);

  root.appendChild(sectionHeader('RESERVE GARRISON', badge(`${total} HELD`, total > 0 ? 'gold' : 'default')));

  if (entries.length === 0) {
    root.appendChild(emptyState('▢', 'no reserves bedded in here'));
    return root;
  }

  const mine = armiesOn(state, hexId).filter(
    (a) => a.ownerId === state.meId && a.path.length === 0 && a.arrivesAt === undefined,
  );
  const take: Partial<Record<UnitType, number>> = {};
  let target: ArmyId | null = mine[0]?.id ?? null;

  const withdrawBtn = button('WITHDRAW', { variant: 'primary', small: true });
  const totalNode = el('span', { class: 'garrison__total mono', text: '0 SELECTED' });

  const syncBtn = (): void => {
    const picked = (Object.values(take) as number[]).reduce((a, b) => a + b, 0);
    const army = target ? state.armies[target] : undefined;
    const room = army ? BATTLE.armyCap - army.units.length : 0;
    totalNode.textContent = `${picked} SELECTED · ${room} SLOTS FREE`;
    withdrawBtn.disabled = picked === 0 || !army || picked > room;
  };

  for (const [type, count] of entries) {
    const def = UNITS[type];
    take[type] = 0;
    const valNode = el('span', { class: 'stepper__val mono tnum', text: '0' });
    const minus = iconButton(ICONS.minus, { small: true, label: `fewer ${def.name}` });
    const plus = iconButton(ICONS.plus, { small: true, label: `more ${def.name}` });

    const paint = (): void => {
      const v = take[type] ?? 0;
      valNode.textContent = String(v);
      minus.disabled = v <= 0;
      plus.disabled = v >= count;
      syncBtn();
    };
    minus.addEventListener('click', () => {
      take[type] = Math.max(0, (take[type] ?? 0) - 1);
      paint();
    });
    plus.addEventListener('click', () => {
      take[type] = Math.min(count, (take[type] ?? 0) + 1);
      paint();
    });

    const art = el('span', { class: 'garrison__art' });
    art.appendChild(svgEl(unitSilhouette(type)));

    root.appendChild(
      el(
        'div',
        { class: 'garrison__row' },
        art,
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'garrison__name display', text: def.name }),
          el('div', { class: 'garrison__sub mono', text: `${count} IN RESERVE` }),
        ),
        el('div', { class: 'stepper' }, minus, valNode, plus),
      ),
    );
    paint();
  }

  if (mine.length > 1) {
    const pick = el('div', { class: 'garrison__pick' });
    for (const army of mine) {
      const b = button(army.name, {
        variant: army.id === target ? 'primary' : 'quiet',
        small: true,
        onClick: () => {
          target = army.id;
          for (const node of Array.from(pick.children)) {
            node.classList.remove('btn--primary');
            node.classList.add('btn--quiet');
          }
          b.classList.remove('btn--quiet');
          b.classList.add('btn--primary');
          syncBtn();
        },
      });
      pick.appendChild(b);
    }
    root.appendChild(sectionHeader('LOAD INTO'));
    root.appendChild(pick);
  }

  withdrawBtn.addEventListener('click', () => {
    const armyId = target;
    if (!armyId) return;
    void (async () => {
      if (await commit(ctx.backend.withdrawUnits(armyId, hexId, { ...take }), 'RESERVES LOADED')) {
        ctx.refresh();
      }
    })();
  });

  root.appendChild(el('div', { class: 'garrison__foot' }, totalNode, withdrawBtn));
  if (mine.length === 0) {
    root.appendChild(
      el('p', { class: 'garrison__note', text: 'A halted column of yours must stand here to take reserves aboard.' }),
    );
  }
  syncBtn();
  ctx.onSync(() => syncBtn());
  return root;
}

// ─────────────────────────────────────────────────────────────────────────────
// Spy drones
// ─────────────────────────────────────────────────────────────────────────────

export interface DroneRoute {
  path: HexId[];
  steps: number;
  etaMs: number;
  /** Cumulative chance of being shot down somewhere along the route. */
  risk: number;
  /** How many legs of the route roll a detection check at all. */
  riskyLegs: number;
}

/** Plan a mote's route and price the risk with the live detection model. */
export function droneRoute(state: GameState, from: HexId, to: HexId): DroneRoute | null {
  if (from === to) return null;
  const path = findPath(
    from,
    to,
    (id) => isHexOpen(state.world, id),
    () => 1,
  );
  if (!path || path.length === 0) return null;

  let survive = 1;
  let riskyLegs = 0;
  for (const id of path) {
    const hex = state.world.hexes[id];
    if (!hex) continue;
    if (!isRiskyHex(state, state.meId, id)) continue;
    riskyLegs++;
    survive *= 1 - detectionChance(hex);
  }
  return {
    path,
    steps: path.length,
    etaMs: path.length * MAP.droneMsPerHex,
    risk: 1 - survive,
    riskyLegs,
  };
}

interface DroneTarget {
  hexId: HexId;
  reason: string;
  route: DroneRoute;
}

function gatherTargets(state: GameState, from: HexId, preferred?: HexId): DroneTarget[] {
  const mine = myFaction(state);
  const seen = new Set<HexId>([from]);
  const out: DroneTarget[] = [];

  const add = (hexId: HexId, reason: string): void => {
    if (seen.has(hexId)) return;
    if (!state.world.hexes[hexId]) return;
    seen.add(hexId);
    const route = droneRoute(state, from, hexId);
    if (!route) return;
    out.push({ hexId, reason, route });
  };

  if (preferred) add(preferred, 'SELECTED ON MAP');
  for (const ping of state.pings) {
    if (ping.guildId === mine) add(ping.hexId, `PING · ${ping.kind.toUpperCase()}`);
  }
  for (const obj of state.objectives) {
    if (obj.guildId !== mine || obj.done) continue;
    for (const id of obj.hexIds) add(id, 'OBJECTIVE');
  }
  for (const mark of state.marks) {
    if (mark.guildId === mine) add(mark.hexId, `MARK · ${mark.label.toUpperCase()}`);
  }
  for (const army of Object.values(state.armies)) {
    if (army.units.length === 0) continue;
    if (!areHostile(state, army.ownerId, state.meId)) continue;
    add(army.hexId, 'HOSTILE COLUMN');
  }
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.gas) continue;
    if (hex.ownerId && factionKey(state, hex.ownerId) === mine) continue;
    if (!isHexOpen(state.world, hex.id)) continue;
    add(hex.id, 'GAS FIELD');
  }
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.ownerId || hex.fortLevel < 2) continue;
    if (!areHostile(state, hex.ownerId, state.meId)) continue;
    add(hex.id, `HOSTILE ${fortTag(hex.fortLevel)}`);
  }

  out.sort((a, b) => hexDistanceId(from, a.hexId) - hexDistanceId(from, b.hexId));
  return out.slice(0, MAX_DRONE_TARGETS);
}

/**
 * Recon control: motes in the field, and a destination picker that prices every
 * candidate route in travel time and cumulative detection risk before launch.
 */
export function dronePanel(
  state: GameState,
  hexId: HexId,
  ctx: PanelCtx,
  hooks: ArmyHooks = {},
  preferred?: HexId,
): HTMLElement {
  const root = el('div', { class: 'recon' });
  const live = aliveDronesOf(state, state.meId);
  const cost = UNITS.drone.cost;

  root.appendChild(
    sectionHeader(
      'RECON CONTROL',
      badge(`${live.length}/${DRONES.maxPerPlayer} AIRBORNE`, live.length > 0 ? 'violet' : 'default'),
    ),
  );

  // ── motes in the field ────────────────────────────────────────────────────
  if (live.length > 0) {
    const list = el('div', { class: 'recon__live' });
    for (const drone of live) {
      const dest = drone.path.length > 0 ? drone.path[drone.path.length - 1] : undefined;
      const row = el('div', { class: 'recon__mote' });
      const art = el('span', { class: 'recon__art' });
      art.appendChild(svgEl(unitSilhouette('drone')));
      row.appendChild(art);

      const info = el(
        'div',
        { class: 'grow' },
        el('div', { class: 'recon__id mono', text: drone.hexId }),
        el('div', {
          class: 'recon__state',
          text: dest ? `RELAYING · INBOUND ${dest.hexId}` : 'RELAYING · STATION KEEPING',
        }),
      );
      row.appendChild(info);

      if (dest) {
        const cd = countdown(dest.arrivesAt, { getNow: ctx.now, compact: true, doneText: 'ON STATION' });
        ctx.onDispose(() => cd.stop());
        row.appendChild(cd.el);
      }
      row.appendChild(
        iconButton(ICONS.close, {
          variant: 'danger',
          small: true,
          label: 'recall mote',
          onClick: () => {
            void (async () => {
              if (await commit(ctx.backend.recallDrone(drone.id), 'MOTE RECALLED')) ctx.refresh();
            })();
          },
        }),
      );
      info.addEventListener('click', () => hooks.onFocusHex?.(drone.hexId));
      list.appendChild(row);
    }
    root.appendChild(list);
  }

  // ── launcher ──────────────────────────────────────────────────────────────
  const targets = gatherTargets(state, hexId, preferred);
  const launchBtn = button('LAUNCH MOTE', {
    variant: 'primary',
    wide: true,
    small: true,
    sub: `${fmtNum(cost.m)} M · ${UNITS.drone.codename}`,
    disabled: true,
  });

  let chosen: DroneTarget | null = null;
  const readout = el('div', { class: 'recon__readout' });
  const rows = new Map<HexId, HTMLElement>();

  const paintReadout = (): void => {
    readout.replaceChildren();
    if (!chosen) {
      readout.appendChild(el('div', { class: 'recon__hint', text: 'SELECT A DESTINATION' }));
      launchBtn.disabled = true;
      return;
    }
    const pct = Math.round(chosen.route.risk * 100);
    const riskBar = meter(pct, 100, {
      color: pct >= 60 ? 'var(--crimson)' : pct >= 25 ? 'var(--amber)' : 'var(--teal)',
      height: 6,
      segments: 10,
    });
    readout.appendChild(statRow('DESTINATION', chosen.hexId, { accent: 'var(--violet)' }));
    readout.appendChild(statRow('ROUTE', `${chosen.route.steps} HEX · ${fmtDuration(chosen.route.etaMs)}`));
    readout.appendChild(
      statRow('EXPOSED LEGS', `${chosen.route.riskyLegs} / ${chosen.route.steps}`, {
        accent: chosen.route.riskyLegs > 0 ? 'var(--amber)' : undefined,
      }),
    );
    readout.appendChild(
      el(
        'div',
        { class: 'recon__risk' },
        el(
          'div',
          { class: 'row' },
          el('span', { class: 'recon__risk-label', text: 'LOSS PROBABILITY' }),
          el('span', { class: 'spacer' }),
          el('span', { class: 'recon__risk-val mono', text: `${pct}%` }),
        ),
        riskBar.el,
      ),
    );
    const player = state.players[state.meId];
    launchBtn.disabled =
      live.length >= DRONES.maxPerPlayer || (player?.minerals ?? 0) < cost.m;
  };

  if (targets.length === 0) {
    root.appendChild(emptyState('◎', 'no route out of this hex — the sector is sealed'));
  } else {
    const picker = el('div', { class: 'recon__targets scroll' });
    for (const t of targets) {
      const pct = Math.round(t.route.risk * 100);
      const hex = state.world.hexes[t.hexId];
      const row = el('button', {
        class: 'recon__target',
        attrs: { type: 'button' },
        data: { risk: pct >= 60 ? 'high' : pct >= 25 ? 'mid' : 'low' },
      });
      row.appendChild(
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'recon__t-id mono', text: t.hexId }),
          el('div', { class: 'recon__t-why', text: t.reason }),
        ),
      );
      row.appendChild(
        el(
          'div',
          { class: 'recon__t-num' },
          el('span', { class: 'mono', text: fmtDuration(t.route.etaMs) }),
          el('span', { class: 'recon__t-risk mono', text: `${pct}%` }),
        ),
      );
      if (hex) row.appendChild(el('span', { class: 'recon__t-terr', text: hex.terrain.toUpperCase() }));
      row.addEventListener('click', () => {
        chosen = t;
        for (const [, node] of rows) node.classList.remove('is-on');
        row.classList.add('is-on');
        haptic(8);
        paintReadout();
      });
      rows.set(t.hexId, row);
      picker.appendChild(row);
    }
    root.appendChild(picker);
  }

  root.appendChild(readout);
  root.appendChild(launchBtn);
  launchBtn.addEventListener('click', () => {
    const target = chosen;
    if (!target) return;
    void (async () => {
      if (
        await commit(
          ctx.backend.launchDrone(hexId, target.hexId),
          'MOTE AWAY',
          `${UNITS.drone.codename} inbound ${target.hexId}`,
        )
      ) {
        ctx.refresh();
      }
    })();
  });

  paintReadout();
  if (preferred) {
    const pre = targets.find((t) => t.hexId === preferred);
    if (pre) {
      chosen = pre;
      rows.get(pre.hexId)?.classList.add('is-on');
      paintReadout();
    }
  }
  return root;
}

/** Coordinates helper used by the map screen's order bar. */
export const hexAxialLabel = (hexId: HexId): string => {
  const a = parseHexId(hexId);
  return `Q${a.q} R${a.r}`;
};
