/**
 * Works: fortification tiers (GDD §6) and the unit production line (GDD §5).
 *
 * Every number on screen is read straight out of `config/balance` (FORTS) and
 * `config/units` (UNITS) — the panel is a window onto the config, never a
 * second copy of it.
 */
import { ECONOMY, FORTS, FORT_RULES } from '../../config';
import { COMBAT_UNIT_TYPES, GAS_GATED, UNITS } from '../../config/units';
import type { Cost, GameState, HexId } from '../../game/types';
import { canBuildFort } from '../../game/world/fortify';
import { canProduce, queuedUnits } from '../../game/world/production';
import { hexYield } from '../../game/world/economy';
import {
  badge,
  button,
  confirmModal,
  countdown,
  emptyState,
  ICONS,
  iconButton,
  meter,
  openModal,
  sectionHeader,
  statRow,
  unitChip,
  unitSilhouette,
  unitStatBlock,
} from '../components';
import { el, fmtDuration, fmtNum, svg as svgEl } from '../dom';
import { commit, fortLabel, type PanelCtx } from './intelPanel';

const TIERS = [1, 2, 3] as const;
type Tier = (typeof TIERS)[number];

function costText(cost: Cost): string {
  return cost.g > 0 ? `${fmtNum(cost.m)} M · ${fmtNum(cost.g)} G` : `${fmtNum(cost.m)} M`;
}

/** Tiny inline mark drawn per fortification tier: post → wall → citadel. */
const TIER_GLYPH: Record<Tier, string> = {
  1: `<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 4l9 5v9l-9 5-9-5V9z"/><path d="M16 13v7"/></svg>`,
  2: `<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M5 24V13l5-3 6 3 6-3 5 3v11z"/><path d="M5 18h22M11 24v-6M21 24v-6"/></svg>`,
  3: `<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M6 27V11l4-4 6 4 6-4 4 4v16z"/><path d="M6 17h20M16 27v-8"/><path d="M16 3v4"/></svg>`,
};

// ─────────────────────────────────────────────────────────────────────────────
// Fortifications
// ─────────────────────────────────────────────────────────────────────────────

/**
 * The three-tier emplacement ladder with live costs, build timers and the exact
 * map / battle effects each tier buys.
 */
export function fortPanel(state: GameState, hexId: HexId, ctx: PanelCtx): HTMLElement {
  const hex = state.world.hexes[hexId];
  const root = el('div', { class: 'works' });
  if (!hex) return root;

  const meId = state.meId;
  const owned = hex.ownerId === meId;

  root.appendChild(
    sectionHeader('EMPLACEMENT', badge(fortLabel(hex.fortLevel), hex.fortLevel > 0 ? 'gold' : 'default')),
  );

  // ── work in progress ──────────────────────────────────────────────────────
  const build = hex.fortBuild;
  if (build) {
    const spec = FORTS[build.targetLevel];
    const total = Math.max(1, build.completesAt - build.startedAt);
    const bar = meter(0, total, { color: 'var(--amber)', height: 6, segments: 8 });
    const cd = countdown(build.completesAt, {
      getNow: ctx.now,
      prefix: 'ETA',
      doneText: 'COMMISSIONING',
    });
    ctx.onDispose(() => cd.stop());
    ctx.onSync((s) => {
      const live = s.world.hexes[hexId]?.fortBuild;
      if (!live) return;
      bar.set(Math.max(0, ctx.now() - live.startedAt), Math.max(1, live.completesAt - live.startedAt));
    });
    bar.set(Math.max(0, ctx.now() - build.startedAt), total);

    const abort = button('ABORT', {
      variant: 'danger',
      small: true,
      onClick: () => {
        void (async () => {
          const yes = await confirmModal({
            title: 'ABORT CONSTRUCTION',
            body: `Stand the crews down at ${hexId}? Half of the ${costText(spec.cost)} outlay is recovered.`,
            confirmLabel: 'STAND DOWN',
            danger: true,
          });
          if (!yes) return;
          if (await commit(ctx.backend.cancelFort(hexId), 'CREWS STOOD DOWN')) ctx.refresh();
        })();
      },
    });

    const card = el(
      'div',
      { class: 'works__wip' },
      el(
        'div',
        { class: 'row' },
        el('span', { class: 'works__wip-title display', text: `RAISING ${spec.label}` }),
        el('span', { class: 'spacer' }),
        cd.el,
      ),
      bar.el,
      el('div', { class: 'row' }, el('span', { class: 'grow dim-2 mono', text: `L${spec.level} · ${costText(spec.cost)}` }), abort),
    );
    root.appendChild(card);
  }

  // ── the ladder ────────────────────────────────────────────────────────────
  const check = canBuildFort(state, meId, hexId);
  const nextLevel = hex.fortLevel < 3 ? ((hex.fortLevel + 1) as Tier) : null;

  for (const tier of TIERS) {
    const spec = FORTS[tier];
    const built = hex.fortLevel >= tier;
    const isNext = nextLevel === tier && !build;
    const row = el('div', {
      class: `tier${built ? ' tier--built' : ''}${isNext ? ' tier--next' : ''}`,
    });

    const mark = el('div', { class: 'tier__mark' });
    mark.appendChild(svgEl(TIER_GLYPH[tier]));
    row.appendChild(mark);

    const main = el('div', { class: 'tier__main' });
    main.appendChild(
      el(
        'div',
        { class: 'tier__head' },
        el('span', { class: 'tier__name display', text: `L${tier} ${spec.label}` }),
        built
          ? badge('ACTIVE', 'ok')
          : el('span', { class: 'tier__cost mono', text: costText(spec.cost) }),
      ),
    );
    main.appendChild(el('div', { class: 'tier__eff', text: `MAP · ${spec.mapEffect}` }));
    main.appendChild(el('div', { class: 'tier__eff tier__eff--war', text: `WAR · ${spec.battleEffect}` }));
    main.appendChild(
      el('div', {
        class: 'tier__time mono',
        text: `CONSTRUCTION ${fmtDuration(spec.buildMs)}`,
      }),
    );
    row.appendChild(main);

    if (isNext && owned) {
      const disabled = !check.ok;
      const btn = button(hex.fortLevel === 0 ? 'BUILD' : 'UPGRADE', {
        variant: 'primary',
        small: true,
        disabled,
        sub: disabled ? undefined : costText(spec.cost),
        onClick: () => {
          void (async () => {
            if (await commit(ctx.backend.buildFort(hexId), 'CREWS DISPATCHED', `${spec.label} at ${hexId}`)) {
              ctx.refresh();
            }
          })();
        },
      });
      const cell = el('div', { class: 'tier__act' }, btn);
      if (disabled && !check.ok) {
        cell.appendChild(el('div', { class: 'tier__why', text: check.error.toUpperCase() }));
      }
      ctx.onSync((s) => {
        const live = canBuildFort(s, s.meId, hexId);
        btn.disabled = !live.ok;
      });
      row.appendChild(cell);
    }

    root.appendChild(row);
  }

  // ── the payoff readout ────────────────────────────────────────────────────
  const y = hexYield(state, hex);
  const foot = el(
    'div',
    { class: 'works__foot' },
    statRow('YIELD / TICK', y.g > 0 ? `${fmtNum(y.m)} M · ${fmtNum(y.g)} G` : `${fmtNum(y.m)} M`, {
      accent: 'var(--teal)',
    }),
    statRow('BONUS AT L2', `+${Math.round(ECONOMY.fortYieldBonus[2] * 100)}%`),
    statRow('SIEGE WAIT AT L3', fmtDuration(FORT_RULES.siegeMs), { accent: 'var(--crimson)' }),
  );
  root.appendChild(foot);

  if (!owned) {
    root.appendChild(
      el('p', { class: 'works__note', text: 'Emplacements can only be raised on ground you hold.' }),
    );
  }
  return root;
}

// ─────────────────────────────────────────────────────────────────────────────
// Production
// ─────────────────────────────────────────────────────────────────────────────

function maxAffordable(minerals: number, gas: number, cost: Cost): number {
  const byM = cost.m > 0 ? Math.floor(minerals / cost.m) : 99;
  const byG = cost.g > 0 ? Math.floor(gas / cost.g) : 99;
  return Math.max(0, Math.min(99, byM, byG));
}

/**
 * The production line: the live queue plus one card per producible chassis with
 * a quantity stepper, gas gating and the full dossier one tap away.
 */
export function productionPanel(state: GameState, hexId: HexId, ctx: PanelCtx): HTMLElement {
  const hex = state.world.hexes[hexId];
  const root = el('div', { class: 'prod' });
  if (!hex) return root;

  const me = state.players[state.meId];
  const owned = hex.ownerId === state.meId;

  root.appendChild(
    sectionHeader(
      'PRODUCTION LINE',
      badge(hex.fortLevel >= 1 ? `${queuedUnits(state, hexId)} QUEUED` : 'OFFLINE', hex.fortLevel >= 1 ? 'default' : 'bad'),
    ),
  );

  if (hex.fortLevel < 1) {
    root.appendChild(
      el(
        'div',
        { class: 'prod__locked hatch' },
        el('div', { class: 'prod__locked-title display', text: 'OUTPOST REQUIRED' }),
        el('p', {
          text: `A level-1 ${FORTS[1].label} (${costText(FORTS[1].cost)}, ${fmtDuration(
            FORTS[1].buildMs,
          )}) has to stand here before a line can be opened.`,
        }),
      ),
    );
    return root;
  }

  // ── queue ─────────────────────────────────────────────────────────────────
  if (hex.production.length > 0) {
    const queue = el('div', { class: 'prod__queue' });
    for (const order of hex.production) {
      const def = UNITS[order.unitType];
      const cd = countdown(order.completesAt, { getNow: ctx.now, compact: true, doneText: 'ROLLING OUT' });
      ctx.onDispose(() => cd.stop());

      const cancel = iconButton(ICONS.close, {
        variant: 'danger',
        small: true,
        label: `cancel ${def.name}`,
        onClick: () => {
          void (async () => {
            if (await commit(ctx.backend.cancelProduction(hexId, order.id), 'ORDER CANCELLED')) ctx.refresh();
          })();
        },
      });

      const art = el('span', { class: 'prod__q-art' });
      art.appendChild(svgEl(unitSilhouette(order.unitType)));
      const row = el(
        'div',
        { class: 'prod__q-row' },
        art,
        el(
          'div',
          { class: 'grow' },
          el('div', { class: 'prod__q-name display', text: def.name }),
          el('div', { class: 'prod__q-sub mono', text: `${order.remaining} REMAINING · ${fmtDuration(def.buildTimeMs)} EACH` }),
        ),
        cd.el,
        cancel,
      );
      queue.appendChild(row);
    }
    root.appendChild(queue);
  } else {
    root.appendChild(emptyState('▤', 'line idle — nothing queued'));
  }

  if (!owned) return root;

  // ── catalogue ─────────────────────────────────────────────────────────────
  root.appendChild(sectionHeader('CHASSIS CATALOGUE'));
  const list = el('div', { class: 'prod__list' });

  for (const type of COMBAT_UNIT_TYPES) {
    const def = UNITS[type];
    const gated = GAS_GATED.includes(type);
    const gasBlocked = gated && (me?.gas ?? 0) < def.cost.g;

    const card = el('div', { class: `prod__card${gasBlocked ? ' prod__card--gated' : ''}` });

    const chip = unitChip(type, {
      small: true,
      onClick: () => {
        openModal({
          title: def.codename,
          body: unitStatBlock(type),
          accent: 'var(--cyan)',
          actions: [{ label: 'CLOSE', variant: 'ghost' }],
        });
      },
    });
    card.appendChild(chip);

    let qty = 1;
    const qtyNode = el('span', { class: 'stepper__val mono tnum', text: '1' });
    const minus = iconButton(ICONS.minus, { small: true, label: 'fewer' });
    const plus = iconButton(ICONS.plus, { small: true, label: 'more' });
    const buildBtn = button('BUILD', { variant: 'primary', small: true, sub: costText(def.cost) });

    const paint = (s: GameState): void => {
      const player = s.players[s.meId];
      const cap = maxAffordable(player?.minerals ?? 0, player?.gas ?? 0, def.cost);
      if (qty > Math.max(1, cap)) qty = Math.max(1, cap);
      qtyNode.textContent = String(qty);
      const check = canProduce(s, s.meId, hexId, type, qty);
      buildBtn.disabled = !check.ok;
      const totalM = def.cost.m * qty;
      const totalG = def.cost.g * qty;
      const sub = buildBtn.querySelector<HTMLElement>('.btn__sub');
      const text = totalG > 0 ? `${fmtNum(totalM)}M ${fmtNum(totalG)}G` : `${fmtNum(totalM)}M`;
      if (sub) sub.textContent = text;
      minus.disabled = qty <= 1;
      plus.disabled = qty >= Math.max(1, cap) || cap === 0;
      card.classList.toggle('prod__card--broke', cap === 0);
    };

    minus.addEventListener('click', () => {
      qty = Math.max(1, qty - 1);
      paint(state);
    });
    plus.addEventListener('click', () => {
      qty = Math.min(99, qty + 1);
      paint(state);
    });
    buildBtn.addEventListener('click', () => {
      void (async () => {
        const n = qty;
        if (
          await commit(
            ctx.backend.produceUnits(hexId, type, n),
            'LINE STARTED',
            `${n} × ${def.name} at ${hexId}`,
          )
        ) {
          ctx.refresh();
        }
      })();
    });

    const controls = el(
      'div',
      { class: 'prod__controls' },
      el('div', { class: 'stepper' }, minus, qtyNode, plus),
      el('span', { class: 'prod__time mono', text: fmtDuration(def.buildTimeMs) }),
      buildBtn,
    );
    card.appendChild(controls);

    if (gasBlocked) {
      card.appendChild(
        el('div', { class: 'prod__gate', text: `GAS-GATED · ${def.cost.g} G PER CHASSIS` }),
      );
    }

    paint(state);
    ctx.onSync(paint);
    list.appendChild(card);
  }

  root.appendChild(list);
  return root;
}
