/**
 * GLOBAL MAP (GDD §12.2) — the game's home screen.
 *
 * Owns a `MapScene` behind the HUD and mirrors the authoritative state into it
 * on every push. On top of the 3D world it lays:
 *   · the sector rotation banner (opening AND closing, with live clocks — §3.2)
 *   · a rolling alerts ticker (drone kills, incoming attacks, shipments, deals)
 *   · a layer rail for pings / marks / intel / objectives / yields
 *   · the column strip with live ETAs and a halt control
 *   · the order bar: pick a column, tap a destination, read the real ETA, commit
 *   · a radial ping menu on long-press, and the selected-hex bottom sheet
 *
 * The scene is kept alive across screen switches and torn down after a spell of
 * inactivity, so the console never holds a WebGL context it is not using.
 */
import '../../styles/map.css';

import type { IBackend } from '../../backend/IBackend';
import { BATTLE, ECONOMY, PING_META, SEASON } from '../../config';
import { PALETTE } from '../../config/visual';
import { focusHex, game, view, type ViewState } from '../../game/store';
import type { Army, ArmyId, GameState, HexId, PingKind, Sector } from '../../game/types';
import { hexYield } from '../../game/world/economy';
import { moveCooldownRemaining } from '../../game/world/movement';
import { upcomingRotation } from '../../game/world/rotation';
import { MapScene } from '../../render/map/MapScene';
import {
  badge,
  button,
  countdown,
  ICONS,
  iconButton,
  promptModal,
  sectionHeader,
  toast,
  type CountdownController,
} from '../components';
import { Disposer, clear, el, fmtAgo, fmtDuration, fmtNum, haptic } from '../dom';
import type { Screen } from '../screen';
import { commit, SimClock, terrainAccent } from '../map/intelPanel';
import { HexSheet, orderVerb, planOrder, type ArmyOrderPlan } from '../map/hexSheet';

/** How long the map may sit unmounted before its WebGL context is released. */
const IDLE_DISPOSE_MS = 25_000;
/** Ticker dwell per alert. */
const TICKER_MS = 4200;
/** Radial menu radius in px. */
const RADIAL_R = 88;

type LayerKey = keyof ViewState['layers'];

const LAYER_ICONS: Record<LayerKey, string> = {
  pings: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="2.4"/><path d="M7.6 7.6a6.2 6.2 0 000 8.8M16.4 16.4a6.2 6.2 0 000-8.8M4.6 4.6a10.4 10.4 0 000 14.8M19.4 19.4a10.4 10.4 0 000-14.8" stroke-linecap="round"/></svg>`,
  marks: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M6 21V3.6"/><path d="M6 4.6h11.5l-2.2 4 2.2 4H6"/></svg>`,
  intel: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2.6 12S6 6.2 12 6.2 21.4 12 21.4 12 18 17.8 12 17.8 2.6 12 2.6 12z"/><circle cx="12" cy="12" r="2.6"/></svg>`,
  objectives: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="7.6"/><path d="M12 2.6v3.2M12 18.2v3.2M2.6 12h3.2M18.2 12h3.2"/><path d="M12 9.4l1.6 3.4-1.6 3.4-1.6-3.4z"/></svg>`,
  yields: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M12 3.2l6 4.6-2.2 11.4H8.2L6 7.8z"/><path d="M6 7.8h12M12 3.2L8.2 19.2M12 3.2l3.8 16"/></svg>`,
};

const LAYER_LABEL: Record<LayerKey, string> = {
  pings: 'PINGS',
  marks: 'MARKS',
  intel: 'INTEL',
  objectives: 'GOALS',
  yields: 'YIELD',
};

const PING_ORDER: PingKind[] = ['attack', 'defend', 'scout', 'rally', 'danger'];

// ─────────────────────────────────────────────────────────────────────────────
// Alerts
// ─────────────────────────────────────────────────────────────────────────────

type AlertTone = 'info' | 'combat' | 'intel' | 'transfer' | 'diplomacy' | 'season' | 'ping';

interface AlertItem {
  id: string;
  at: number;
  tone: AlertTone;
  text: string;
  hexId?: HexId;
}

const ALERT_GLYPH: Record<AlertTone, string> = {
  info: '▚',
  combat: '⚔',
  intel: '◎',
  transfer: '⇄',
  diplomacy: '✎',
  season: '◐',
  ping: '⚑',
};

function collectAlerts(state: GameState): AlertItem[] {
  const me = state.players[state.meId];
  const myFaction = me?.guildId ?? state.meId;
  const out: AlertItem[] = [];

  for (const n of state.notifications) {
    const tone: AlertTone =
      n.kind === 'alert' ? 'combat' : n.kind === 'diplomacy' ? 'diplomacy' : (n.kind as AlertTone);
    out.push({ id: n.id, at: n.at, tone, text: `${n.title} — ${n.body}`, hexId: n.hexId });
  }

  for (const ping of state.pings) {
    if (ping.guildId !== myFaction) continue;
    if (ping.expiresAt <= state.now) continue;
    out.push({
      id: ping.id,
      at: ping.at,
      tone: 'ping',
      text: `${PING_META[ping.kind].label} PING · ${ping.hexId} · ${ping.authorName}`,
      hexId: ping.hexId,
    });
  }

  for (const t of state.transfers) {
    if (t.status !== 'in_transit') continue;
    if (t.toId !== state.meId && t.fromId !== state.meId) continue;
    const inbound = t.toId === state.meId;
    const other = state.players[inbound ? t.fromId : t.toId]?.name ?? 'UNKNOWN';
    out.push({
      id: `tr:${t.id}`,
      at: t.sentAt,
      tone: 'transfer',
      text: `${inbound ? 'INBOUND' : 'OUTBOUND'} SHIPMENT ${inbound ? 'FROM' : 'TO'} ${other} · LANDS IN ${fmtDuration(
        Math.max(0, t.arrivesAt - state.now),
      )}`,
    });
  }

  for (const treaty of Object.values(state.treaties)) {
    if (treaty.status !== 'signed' || treaty.signedAt === undefined) continue;
    if (!treaty.guilds.includes(myFaction)) continue;
    out.push({
      id: `ty:${treaty.id}`,
      at: treaty.signedAt,
      tone: 'diplomacy',
      text: `TREATY SIGNED · ${treaty.title}`,
    });
  }

  for (const pb of state.pendingBattles) {
    if (pb.defenderId !== state.meId && pb.attackerId !== state.meId) continue;
    out.push({
      id: `pb:${pb.id}`,
      at: pb.graceEndsAt - BATTLE.defenderGraceMs,
      tone: 'combat',
      text: `ENGAGEMENT PENDING AT ${pb.hexId} — GRACE WINDOW RUNNING`,
      hexId: pb.hexId,
    });
  }

  out.sort((a, b) => b.at - a.at);
  return out.slice(0, 12);
}

// ─────────────────────────────────────────────────────────────────────────────
// Order flow
// ─────────────────────────────────────────────────────────────────────────────

type OrderState =
  | { kind: 'idle' }
  | { kind: 'picking'; armyId: ArmyId }
  | { kind: 'preview'; plan: ArmyOrderPlan };

// ─────────────────────────────────────────────────────────────────────────────
// Screen
// ─────────────────────────────────────────────────────────────────────────────

export function createMapScreen(backend: IBackend): Screen {
  const root = el('div', { class: 'screen map-screen' });
  const clock = new SimClock();

  // ── scene host ────────────────────────────────────────────────────────────
  const sceneHost = el('div', { class: 'map-scene' });
  root.appendChild(sceneHost);

  let scene: MapScene | null = null;
  let idleHandle = 0;
  let mounted = false;

  // ── chrome ────────────────────────────────────────────────────────────────
  const rotationSlot = el('div', { class: 'rot' });
  const tickerSlot = el('div', { class: 'ticker' });
  const top = el('div', { class: 'map-top' }, rotationSlot, tickerSlot);

  const rail = el('div', { class: 'map-rail' });
  const railButtons = new Map<LayerKey, HTMLButtonElement>();

  const ledger = el('div', { class: 'ledger hidden' });
  const columnSlot = el('div', { class: 'columns scroll-x no-scrollbar' });
  const orderSlot = el('div', { class: 'orderbar' });
  const bottom = el('div', { class: 'map-bottom' }, ledger, columnSlot, orderSlot);

  root.appendChild(top);
  root.appendChild(rail);
  root.appendChild(bottom);

  // ── bottom sheet ──────────────────────────────────────────────────────────
  const sheet = new HexSheet({
    backend,
    now: () => clock.now(),
    onOrderArmy: (armyId, dest) => beginOrder(armyId, dest),
    onPingMenu: (hexId) => openRadial(hexId),
    onFocusHex: (hexId) => focusHex(hexId),
  });
  sheet.sheet.onClose(() => {
    if (view.get().selectedHexId !== undefined) view.patch({ selectedHexId: undefined });
  });
  root.appendChild(sheet.el);

  // ── radial menu ───────────────────────────────────────────────────────────
  const radial = el('div', { class: 'radial', aria: { hidden: 'true' } });
  root.appendChild(radial);

  // ── live state ────────────────────────────────────────────────────────────
  let order: OrderState = { kind: 'idle' };
  let alerts: AlertItem[] = [];
  let alertIndex = 0;
  let alertTimer = 0;
  let rotationSig = '';
  let columnSig = '';
  let ledgerSig = '';
  let alertSig = '';
  let orderSig = '';
  let tickerKey = '';
  let tickerAge: HTMLElement | null = null;

  /** Countdown controllers, held per section so each can stop only its own. */
  const rotTimers: CountdownController[] = [];
  const colTimers: CountdownController[] = [];
  const ordTimers: CountdownController[] = [];

  const stopAll = (list: CountdownController[]): void => {
    for (const t of list.splice(0)) t.stop();
  };

  const stateOrNull = (): GameState | null => game.get();

  /**
   * How much longer this column has to regroup before it may be given a new
   * march order (0 = free). Read off the interpolated sim clock so the readout
   * runs smoothly between the backend's 5 Hz pushes.
   */
  const regroupMs = (army: Army): number => moveCooldownRemaining(army, clock.now());

  // ── scene wiring ──────────────────────────────────────────────────────────
  function buildScene(): void {
    if (scene) return;
    const created = new MapScene(sceneHost);
    created.onHexTap((hexId) => onHexTap(hexId));
    created.onHexLongPress((hexId) => openRadial(hexId));
    created.onEmptyTap(() => {
      sheet.close();
      if (order.kind !== 'idle') cancelOrder();
    });
    scene = created;
  }

  function teardownScene(): void {
    if (!scene) return;
    scene.dispose();
    scene = null;
  }

  // ── order flow ────────────────────────────────────────────────────────────
  function beginOrder(armyId: ArmyId, dest?: HexId): void {
    const state = stateOrNull();
    if (!state) return;
    const army = state.armies[armyId];
    if (!army) return;
    view.patch({ selectedArmyId: armyId });

    // Refuse to open the order flow at all while the column is regrouping —
    // plotting a march you cannot commit is worse than being told why.
    const cooling = regroupMs(army);
    if (cooling > 0) {
      toast({
        title: 'COLUMN REGROUPING',
        body: `${army.name} holds ${army.hexId}. It can march again in ${fmtDuration(cooling)}.`,
        kind: 'warn',
      });
      order = { kind: 'idle' };
      applyPreview(state);
      renderOrderBar(state);
      focusHex(army.hexId);
      return;
    }

    if (dest) {
      const plan = planOrder(state, armyId, dest);
      if (!plan.ok) {
        toast({ title: 'NO ROUTE', body: plan.error, kind: 'bad' });
        order = { kind: 'picking', armyId };
      } else {
        order = { kind: 'preview', plan: plan.value };
      }
    } else {
      order = { kind: 'picking', armyId };
    }
    applyPreview(state);
    renderOrderBar(state);
    focusHex(dest ?? army.hexId);
    haptic(12);
  }

  function cancelOrder(): void {
    order = { kind: 'idle' };
    view.patch({ previewPath: [], selectedArmyId: undefined });
    const state = stateOrNull();
    if (state) renderOrderBar(state);
  }

  function applyPreview(state: GameState): void {
    if (order.kind !== 'preview') {
      if (view.get().previewPath.length > 0) view.patch({ previewPath: [] });
      return;
    }
    const army = state.armies[order.plan.armyId];
    const path = [army ? army.hexId : order.plan.from, ...order.plan.path];
    view.patch({ previewPath: path });
  }

  function onHexTap(hexId: HexId): void {
    const state = stateOrNull();
    if (!state) return;
    haptic(9);

    if (order.kind === 'picking' || order.kind === 'preview') {
      const armyId = order.kind === 'picking' ? order.armyId : order.plan.armyId;
      const army = state.armies[armyId];
      if (!army) {
        cancelOrder();
        return;
      }
      if (army.hexId === hexId) {
        toast({ title: 'ALREADY THERE', body: `${army.name} holds ${hexId}.`, kind: 'warn' });
        return;
      }
      const plan = planOrder(state, armyId, hexId);
      if (!plan.ok) {
        toast({ title: 'NO ROUTE', body: plan.error, kind: 'bad' });
        return;
      }
      order = { kind: 'preview', plan: plan.value };
      applyPreview(state);
      renderOrderBar(state);
      scene?.pulse(hexId, PALETTE.cyan);
      return;
    }

    view.patch({ selectedHexId: hexId });
    sheet.open(hexId);
  }

  function confirmOrder(): void {
    if (order.kind !== 'preview') return;
    const { armyId, dest, armyName } = order.plan;
    void (async () => {
      const done = await commit(
        backend.moveArmy(armyId, dest),
        'ORDERS TRANSMITTED',
        `${armyName} marching on ${dest}`,
      );
      if (!done) return;
      scene?.pulse(dest, PALETTE.teal);
      order = { kind: 'idle' };
      view.patch({ previewPath: [] });
      const state = stateOrNull();
      if (state) renderOrderBar(state);
    })();
  }

  // ── radial ping menu ──────────────────────────────────────────────────────
  function closeRadial(): void {
    radial.classList.remove('is-open');
    radial.setAttribute('aria-hidden', 'true');
    window.setTimeout(() => {
      if (!radial.classList.contains('is-open')) clear(radial);
    }, 220);
  }

  function openRadial(hexId: HexId): void {
    clear(radial);
    haptic([12, 30, 12]);

    const scrim = el('div', { class: 'radial__scrim' });
    scrim.addEventListener('pointerdown', (ev: PointerEvent) => {
      ev.preventDefault();
      closeRadial();
    });
    radial.appendChild(scrim);

    const wheel = el('div', { class: 'radial__wheel' });
    const state = stateOrNull();
    const hex = state?.world.hexes[hexId];
    wheel.appendChild(
      el(
        'div',
        {
          class: 'radial__hub',
          style: hex ? `--accent:${terrainAccent(hex.terrain)}` : undefined,
        },
        el('span', { class: 'radial__hub-id mono', text: hexId }),
        el('span', { class: 'radial__hub-t', text: hex ? hex.terrain.toUpperCase() : 'UNKNOWN' }),
      ),
    );

    PING_ORDER.forEach((kind, i) => {
      const meta = PING_META[kind];
      const angle = -90 + (360 / PING_ORDER.length) * i;
      const node = el('button', {
        class: 'radial__spoke',
        attrs: { type: 'button' },
        style: `--accent:${meta.color};transform:rotate(${angle}deg) translate(${RADIAL_R}px) rotate(${-angle}deg)`,
        aria: { label: `${meta.label} ping` },
      });
      node.appendChild(el('span', { class: 'radial__glyph', text: meta.glyph }));
      node.appendChild(el('span', { class: 'radial__label', text: meta.label }));
      node.addEventListener('click', () => {
        closeRadial();
        void (async () => {
          if (await commit(backend.placePing(hexId, kind), `${meta.label} PING SENT`, hexId)) {
            scene?.pulse(hexId, parseInt(meta.color.slice(1), 16));
          }
        })();
      });
      wheel.appendChild(node);
    });

    radial.appendChild(wheel);

    const extras = el(
      'div',
      { class: 'radial__extras' },
      button('PLACE MARK', {
        variant: 'ghost',
        small: true,
        onClick: () => {
          closeRadial();
          void (async () => {
            const label = await promptModal({
              title: 'MAP MARK',
              label: `Annotation for ${hexId}`,
              placeholder: 'STAGING POINT',
              maxLength: 28,
              uppercase: true,
            });
            if (label === null) return;
            await commit(backend.placeMark(hexId, label), 'MARK PLACED', hexId);
          })();
        },
      }),
      button('SET OBJECTIVE', {
        variant: 'ghost',
        small: true,
        onClick: () => {
          closeRadial();
          void (async () => {
            const title = await promptModal({
              title: 'GUILD OBJECTIVE',
              label: `Objective on ${hexId}`,
              placeholder: 'TAKE THE VENT',
              maxLength: 48,
            });
            if (title === null) return;
            const detail = await promptModal({
              title: 'BRIEFING',
              label: 'What does the guild need to do?',
              placeholder: 'Two columns minimum. Hold through the rotation.',
              multiline: true,
              maxLength: 320,
              required: false,
            });
            await commit(
              backend.createObjective({
                title,
                detail: detail ?? '',
                hexIds: [hexId],
                grand: false,
              }),
              'OBJECTIVE POSTED',
              title,
            );
          })();
        },
      }),
      button('OPEN HEX', {
        variant: 'quiet',
        small: true,
        onClick: () => {
          closeRadial();
          view.patch({ selectedHexId: hexId });
          sheet.open(hexId);
        },
      }),
    );
    radial.appendChild(extras);

    radial.classList.add('is-open');
    radial.setAttribute('aria-hidden', 'false');
  }

  // ── rail ──────────────────────────────────────────────────────────────────
  function buildRail(): void {
    clear(rail);
    railButtons.clear();
    const keys: LayerKey[] = ['pings', 'marks', 'intel', 'objectives', 'yields'];
    for (const key of keys) {
      const btn = iconButton(LAYER_ICONS[key], {
        label: `${LAYER_LABEL[key]} layer`,
        class: 'rail__btn',
        onClick: () => {
          const layers = { ...view.get().layers };
          layers[key] = !layers[key];
          view.patch({ layers });
          haptic(8);
        },
      });
      btn.appendChild(el('span', { class: 'rail__tag', text: LAYER_LABEL[key] }));
      railButtons.set(key, btn);
      rail.appendChild(btn);
    }
  }

  function syncRail(v: ViewState): void {
    for (const [key, btn] of railButtons) {
      btn.classList.toggle('icon-btn--on', v.layers[key]);
    }
  }

  // ── rotation banner ───────────────────────────────────────────────────────
  function renderRotation(state: GameState): void {
    const rot = upcomingRotation(state, state.now);
    const sig = `${rot.opening?.id ?? '-'}|${rot.closing?.id ?? '-'}|${rot.at}`;
    if (sig === rotationSig) return;
    rotationSig = sig;
    stopAll(rotTimers);
    clear(rotationSlot);

    const slab = (
      sector: Sector | undefined,
      mode: 'open' | 'close',
      at: number,
    ): HTMLElement => {
      const node = el('div', { class: `rot__slab rot__slab--${mode}` });
      node.appendChild(
        el('span', { class: 'rot__kicker', text: mode === 'open' ? 'UNSEALING' : 'SHUTDOWN' }),
      );
      node.appendChild(
        el('span', { class: 'rot__name display truncate', text: sector?.designation ?? 'UNDISCLOSED' }),
      );
      const cd = countdown(at, { getNow: () => clock.now(), compact: true, doneText: 'NOW' });
      rotTimers.push(cd);
      node.appendChild(cd.el);
      if (sector) {
        node.addEventListener('click', () => {
          focusHex(`${sector.center.q},${sector.center.r}`);
          haptic(9);
        });
      }
      return node;
    };

    if (rot.opening || rot.closing) {
      const wrap = el('div', { class: 'rot__pair' });
      wrap.appendChild(slab(rot.opening, 'open', rot.at));
      wrap.appendChild(slab(rot.closing, 'close', rot.at));
      rotationSlot.appendChild(wrap);
    } else {
      const revealAt = rot.at - SEASON.announceMs;
      const cd = countdown(revealAt, {
        getNow: () => clock.now(),
        prefix: 'REVEAL IN',
        doneText: 'DECRYPTING',
      });
      rotTimers.push(cd);
      rotationSlot.appendChild(
        el(
          'div',
          { class: 'rot__sealed hatch--cold' },
          el('span', { class: 'rot__kicker', text: 'ROTATION ORDER SEALED' }),
          cd.el,
        ),
      );
    }
  }

  // ── ticker ────────────────────────────────────────────────────────────────
  function renderTicker(state: GameState): void {
    const next = collectAlerts(state);
    const sig = next.map((a) => a.id).join(',');
    alerts = next;
    if (sig !== alertSig) {
      alertSig = sig;
      if (alertIndex >= alerts.length) alertIndex = 0;
      alertTimer = 0;
    }
    paintTicker(state);
  }

  /** Rebuilds only when the visible alert actually changes; ages tick in place. */
  function paintTicker(state: GameState): void {
    const item = alerts.length > 0 ? alerts[alertIndex % alerts.length] : null;
    const key = item ? `${item.id}#${alertIndex % alerts.length}/${alerts.length}` : 'idle';
    if (key === tickerKey) {
      if (item && tickerAge) tickerAge.textContent = fmtAgo(item.at, state.now);
      return;
    }
    tickerKey = key;
    tickerAge = null;
    clear(tickerSlot);

    if (!item) {
      tickerSlot.appendChild(
        el(
          'div',
          { class: 'ticker__row ticker__row--idle' },
          el('span', { class: 'ticker__glyph', text: '▚' }),
          el('span', { class: 'ticker__text', text: 'ALL QUIET ON THE NET' }),
        ),
      );
      return;
    }

    const age = el('span', { class: 'ticker__age mono', text: fmtAgo(item.at, state.now) });
    tickerAge = age;
    const row = el(
      'div',
      { class: `ticker__row ticker__row--${item.tone}` },
      el('span', { class: 'ticker__glyph', text: ALERT_GLYPH[item.tone] }),
      el('span', { class: 'ticker__text truncate', text: item.text }),
      age,
      el('span', {
        class: 'ticker__pips mono',
        text: `${(alertIndex % alerts.length) + 1}/${alerts.length}`,
      }),
    );
    if (item.hexId) {
      const hexId = item.hexId;
      row.addEventListener('click', () => {
        focusHex(hexId);
        view.patch({ selectedHexId: hexId });
        sheet.open(hexId);
      });
      row.classList.add('is-tappable');
    }
    tickerSlot.appendChild(row);
  }

  // ── column strip ──────────────────────────────────────────────────────────
  function renderColumns(state: GameState): void {
    const mine: Army[] = Object.values(state.armies)
      .filter((a) => a.ownerId === state.meId)
      .sort((a, b) => (a.name < b.name ? -1 : 1));
    const sig = mine
      .map(
        (a) =>
          `${a.id}:${a.hexId}:${a.units.length}:${a.path.length}:${a.arrivesAt ?? 0}:${
            a.siege ? 1 : 0
          }:${moveCooldownRemaining(a, state.now) > 0 ? 1 : 0}`,
      )
      .join('|');
    const selected = view.get().selectedArmyId ?? '';
    if (sig + selected === columnSig) return;
    columnSig = sig + selected;
    stopAll(colTimers);
    clear(columnSlot);

    if (mine.length === 0) {
      columnSlot.appendChild(
        el('div', { class: 'columns__empty', text: 'NO COLUMNS IN THE FIELD — PRODUCE OR MOBILISE' }),
      );
      return;
    }

    for (const army of mine) {
      const moving = army.arrivesAt !== undefined || army.path.length > 0;
      // Three mutually exclusive states, three accents: marching (gold),
      // regrouping (violet), holding (cyan).
      const cooling = !moving && regroupMs(army) > 0;
      const chip = el('div', {
        class: `col-chip${moving ? ' col-chip--moving' : ''}${cooling ? ' col-chip--cooling' : ''}${
          army.id === selected ? ' is-sel' : ''
        }`,
      });

      chip.appendChild(
        el(
          'div',
          { class: 'col-chip__head' },
          el('span', { class: 'col-chip__name display truncate', text: army.name }),
          badge(`${army.units.length}`, moving ? 'gold' : cooling ? 'violet' : 'ok'),
        ),
      );

      if (army.siege) {
        const cd = countdown(army.siege.readyAt, { getNow: () => clock.now(), compact: true, doneText: 'BREACH' });
        colTimers.push(cd);
        chip.appendChild(el('div', { class: 'col-chip__line' }, el('span', { text: 'SIEGE' }), cd.el));
      } else if (moving && army.path.length > 0) {
        const last = army.path[army.path.length - 1];
        const cd = countdown(last.arrivesAt, { getNow: () => clock.now(), compact: true, doneText: 'ARRIVED' });
        colTimers.push(cd);
        chip.appendChild(
          el('div', { class: 'col-chip__line' }, el('span', { class: 'mono', text: `→ ${last.hexId}` }), cd.el),
        );
      } else if (cooling && army.moveReadyAt !== undefined) {
        const cd = countdown(army.moveReadyAt, {
          getNow: () => clock.now(),
          prefix: 'READY IN',
          doneText: 'READY',
          class: 'col-chip__ready',
        });
        colTimers.push(cd);
        chip.appendChild(
          el('div', { class: 'col-chip__line' }, el('span', { class: 'mono', text: army.hexId }), cd.el),
        );
      } else {
        chip.appendChild(
          el('div', { class: 'col-chip__line' }, el('span', { class: 'mono', text: army.hexId }), el('span', { class: 'ok-t', text: 'HOLDING' })),
        );
      }

      chip.addEventListener('click', () => {
        view.patch({ selectedArmyId: army.id, selectedHexId: army.hexId });
        focusHex(army.hexId);
        haptic(9);
        const s = stateOrNull();
        if (s) renderOrderBar(s);
      });

      if (moving) {
        chip.appendChild(
          iconButton(ICONS.close, {
            variant: 'danger',
            small: true,
            label: `halt ${army.name}`,
            class: 'col-chip__halt',
            onClick: () => {
              void commit(backend.haltArmy(army.id), 'COLUMN HALTED', army.name);
            },
          }),
        );
      }

      columnSlot.appendChild(chip);
    }
  }

  // ── order bar ─────────────────────────────────────────────────────────────
  function orderBarSignature(state: GameState): string {
    if (order.kind === 'picking') return `pick:${order.armyId}`;
    if (order.kind === 'preview') {
      const p = order.plan;
      return `prev:${p.armyId}:${p.dest}:${p.steps}:${p.etaMs}:${p.siegeMs}:${p.contested ? 1 : 0}`;
    }
    const sel = view.get().selectedArmyId;
    const army = sel ? state.armies[sel] : undefined;
    if (!army) return 'idle';
    const cool = moveCooldownRemaining(army, state.now) > 0 ? 1 : 0;
    return `sel:${army.id}:${army.units.length}:${army.hexId}:${army.path.length}:${army.arrivesAt ?? 0}:${cool}`;
  }

  function renderOrderBar(state: GameState): void {
    const sig = orderBarSignature(state);
    if (sig === orderSig) return;
    orderSig = sig;
    stopAll(ordTimers);
    clear(orderSlot);
    const selectedArmyId = view.get().selectedArmyId;

    if (order.kind === 'picking') {
      const army = state.armies[order.armyId];
      orderSlot.appendChild(
        el(
          'div',
          { class: 'orderbar__inner orderbar__inner--pick' },
          el(
            'div',
            { class: 'grow' },
            el('div', { class: 'orderbar__title display', text: army?.name ?? 'COLUMN' }),
            el('div', { class: 'orderbar__sub', text: 'TAP A HEX TO PLOT THE MARCH' }),
          ),
          button('CANCEL', { variant: 'quiet', small: true, onClick: () => cancelOrder() }),
        ),
      );
      return;
    }

    if (order.kind === 'preview') {
      const plan = order.plan;
      const total = plan.etaMs + plan.siegeMs;
      const verb = orderVerb(state, plan.dest);
      const inner = el('div', { class: 'orderbar__inner orderbar__inner--preview' });
      inner.appendChild(
        el(
          'div',
          { class: 'grow' },
          el(
            'div',
            { class: 'orderbar__title display truncate' },
            el('span', { text: plan.armyName }),
            el('span', { class: 'orderbar__arrow', text: '→' }),
            el('span', { class: 'mono', text: plan.dest }),
          ),
          el('div', {
            class: 'orderbar__sub mono',
            text: `${plan.steps} HEX · ${fmtDuration(total)}${plan.siegeMs > 0 ? ` · SIEGE ${fmtDuration(plan.siegeMs)}` : ''}${
              plan.contested ? ' · DEFENDED' : ''
            }`,
          }),
        ),
      );
      inner.appendChild(button('CANCEL', { variant: 'quiet', small: true, onClick: () => cancelOrder() }));
      inner.appendChild(
        button(verb, { variant: plan.contested ? 'danger' : 'primary', small: true, onClick: () => confirmOrder() }),
      );
      orderSlot.appendChild(inner);
      return;
    }

    if (!selectedArmyId) return;
    const army = state.armies[selectedArmyId];
    if (!army) return;
    const moving = army.arrivesAt !== undefined || army.path.length > 0;
    const cooling = !moving && regroupMs(army) > 0;

    const info = el(
      'div',
      { class: 'grow' },
      el('div', { class: 'orderbar__title display truncate', text: army.name }),
      el('div', {
        class: 'orderbar__sub mono',
        text: `${army.units.length} CHASSIS · ${army.hexId}${
          moving ? ' · IN TRANSIT' : cooling ? ' · REGROUPING' : ''
        }`,
      }),
    );

    const inner = el('div', { class: `orderbar__inner${cooling ? ' orderbar__inner--cool' : ''}` }, info);

    if (moving) {
      inner.appendChild(
        button('HALT', {
          variant: 'danger',
          small: true,
          onClick: () => {
            void commit(backend.haltArmy(army.id), 'COLUMN HALTED', army.name);
          },
        }),
      );
    }

    const marchBtn = button(moving ? 'RE-ROUTE' : 'MARCH', {
      variant: 'primary',
      small: true,
      disabled: cooling,
      onClick: () => beginOrder(army.id),
    });

    // Say WHY the order is unavailable, and re-arm the button the moment the
    // column is ready rather than waiting on the next state push.
    if (cooling && army.moveReadyAt !== undefined) {
      const cd = countdown(army.moveReadyAt, {
        getNow: () => clock.now(),
        prefix: 'DUG IN · READY IN',
        doneText: 'READY TO MARCH',
        class: 'orderbar__cool-cd',
        onDone: () => {
          marchBtn.disabled = false;
          inner.classList.remove('orderbar__inner--cool');
        },
      });
      ordTimers.push(cd);
      info.appendChild(el('div', { class: 'orderbar__cool' }, cd.el));
    }

    inner.appendChild(marchBtn);
    inner.appendChild(
      button('CLEAR', {
        variant: 'quiet',
        small: true,
        onClick: () => {
          view.patch({ selectedArmyId: undefined });
          const s = stateOrNull();
          if (s) renderOrderBar(s);
        },
      }),
    );
    orderSlot.appendChild(inner);
  }

  // ── yield ledger ──────────────────────────────────────────────────────────
  function renderLedger(state: GameState): void {
    const on = view.get().layers.yields;
    ledger.classList.toggle('hidden', !on);
    if (!on) {
      ledgerSig = '';
      return;
    }
    const holdings = Object.values(state.world.hexes)
      .filter((h) => h.ownerId === state.meId)
      .map((h) => ({ hex: h, y: hexYield(state, h) }))
      .sort((a, b) => b.y.m + b.y.g * 8 - (a.y.m + a.y.g * 8));
    const sig = holdings.map((h) => `${h.hex.id}:${h.y.m}:${h.y.g}`).join('|');
    if (sig === ledgerSig) return;
    ledgerSig = sig;
    clear(ledger);

    const totalM = holdings.reduce((n, h) => n + h.y.m, 0);
    const totalG = holdings.reduce((n, h) => n + h.y.g, 0);

    ledger.appendChild(
      sectionHeader(
        'YIELD LEDGER',
        badge(`${holdings.length} HEX`, holdings.length > 0 ? 'ok' : 'bad'),
      ),
    );
    ledger.appendChild(
      el(
        'div',
        { class: 'ledger__total' },
        el('span', { class: 'mono', text: `${fmtNum(totalM)} M / TICK` }),
        el('span', { class: 'mono ok-t', text: `${fmtNum(totalG)} G / TICK` }),
        el('span', { class: 'dim-2 mono', text: `TICK ${fmtDuration(ECONOMY.tickMs)}` }),
      ),
    );

    const list = el('div', { class: 'ledger__list scroll' });
    for (const row of holdings.slice(0, 24)) {
      const node = el('button', {
        class: 'ledger__row',
        attrs: { type: 'button' },
        style: `--accent:${terrainAccent(row.hex.terrain)}`,
      });
      node.appendChild(el('span', { class: 'ledger__id mono', text: row.hex.id }));
      node.appendChild(el('span', { class: 'ledger__terr truncate', text: row.hex.terrain.toUpperCase() }));
      node.appendChild(el('span', { class: 'ledger__m mono', text: `${fmtNum(row.y.m)}M` }));
      if (row.y.g > 0) node.appendChild(el('span', { class: 'ledger__g mono', text: `${fmtNum(row.y.g)}G` }));
      if (row.hex.fortLevel > 0) node.appendChild(badge(`L${row.hex.fortLevel}`, 'gold'));
      node.addEventListener('click', () => {
        focusHex(row.hex.id);
        view.patch({ selectedHexId: row.hex.id });
        sheet.open(row.hex.id);
      });
      list.appendChild(node);
    }
    if (holdings.length === 0) {
      list.appendChild(el('div', { class: 'ledger__empty', text: 'YOU HOLD NO GROUND' }));
    }
    ledger.appendChild(list);
  }

  // ── sync ──────────────────────────────────────────────────────────────────
  function syncAll(): void {
    const state = stateOrNull();
    if (!state) return;
    clock.sync(state.now);
    const v = view.get();

    scene?.sync(state, v);
    syncRail(v);

    // A vanished column invalidates any order in flight.
    if (order.kind === 'picking' && !state.armies[order.armyId]) cancelOrder();
    if (order.kind === 'preview' && !state.armies[order.plan.armyId]) cancelOrder();

    renderRotation(state);
    renderTicker(state);
    renderColumns(state);
    renderOrderBar(state);
    renderLedger(state);
    sheet.sync(state);
  }

  // ── lifecycle ─────────────────────────────────────────────────────────────
  const disposer = new Disposer();

  window.addEventListener('pagehide', () => {
    window.clearTimeout(idleHandle);
    teardownScene();
  });

  buildRail();

  return {
    el: root,

    mount(): void {
      if (mounted) return;
      mounted = true;
      window.clearTimeout(idleHandle);
      buildScene();
      scene?.resize();

      disposer.add(game.subscribe(() => syncAll()));
      disposer.add(view.subscribe(() => syncAll()));
      disposer.listen(window, 'resize', () => scene?.resize());

      // Re-frame on the first mount of a session.
      const state = stateOrNull();
      if (state) {
        const v = view.get();
        if (!v.selectedHexId) {
          const home = Object.values(state.armies).find((a) => a.ownerId === state.meId);
          if (home) focusHex(home.hexId);
        }
      }
      syncAll();
    },

    unmount(): void {
      if (!mounted) return;
      mounted = false;
      disposer.dispose();
      stopAll(rotTimers);
      stopAll(colTimers);
      stopAll(ordTimers);
      sheet.close();
      closeRadial();
      if (order.kind !== 'idle') cancelOrder();
      rotationSig = '';
      columnSig = '';
      ledgerSig = '';
      alertSig = '';
      orderSig = '';
      tickerKey = '';
      tickerAge = null;
      window.clearTimeout(idleHandle);
      idleHandle = window.setTimeout(() => teardownScene(), IDLE_DISPOSE_MS);
    },

    frame(dt: number): void {
      if (!mounted) return;
      if (alerts.length > 1) {
        alertTimer += dt;
        if (alertTimer >= TICKER_MS) {
          alertTimer = 0;
          alertIndex = (alertIndex + 1) % alerts.length;
          const state = stateOrNull();
          if (state) paintTicker(state);
        }
      }
    },
  };
}
