/**
 * The selected-hex bottom sheet (GDD §12.2).
 *
 * One sheet, four faces: ground you hold, ground a rival holds, open ground,
 * and ground nobody has looked at in a while. It re-renders only when the hex
 * actually changes shape (owner, fort, queue, garrison, columns) so steppers
 * and selections survive the 5 Hz backend push.
 */
import type { IBackend } from '../../backend/IBackend';
import { FORT_RULES, MAP, TERRAIN_META } from '../../config';
import type {
  Army,
  ArmyId,
  GameState,
  Hex,
  HexId,
  PlayerId,
  Result,
  Sector,
} from '../../game/types';
import { err, ok } from '../../game/types';
import { hexDistanceId, neighborIds } from '../../game/hex';
import { hexYield } from '../../game/world/economy';
import {
  captureDurationMs,
  areHostile,
  hostileArmyOnHex,
  moveCooldownRemaining,
  planPath,
  stepMs,
} from '../../game/world/movement';
import {
  badge,
  BottomSheet,
  button,
  countdown,
  emptyState,
  sectionHeader,
  statRow,
  tabs,
  toast,
  type TabsController,
} from '../components';
import { el, fmtDuration, fmtNum, haptic, svg as svgEl } from '../dom';
import {
  fortTag,
  intelPanel,
  observesHex,
  terrainAccent,
  terrainArt,
  factionKey,
  type PanelCtx,
} from './intelPanel';
import { fortPanel, productionPanel } from './buildPanel';
import { armiesOn, armiesPanel, dronePanel, foreignArmiesPanel, garrisonPanel, type ArmyHooks } from './armyPanel';

// ─────────────────────────────────────────────────────────────────────────────
// Order planning — shared with the map screen's order bar
// ─────────────────────────────────────────────────────────────────────────────

export interface ArmyOrderPlan {
  armyId: ArmyId;
  armyName: string;
  from: HexId;
  dest: HexId;
  /** Hexes entered, start-exclusive, destination-inclusive. */
  path: HexId[];
  steps: number;
  /** Marching time only. */
  etaMs: number;
  /** Extra wait imposed by a Citadel standing on the destination. */
  siegeMs: number;
  /** True when a hostile column is already standing on the destination. */
  contested: boolean;
}

/**
 * Price a march with the real movement rules: A* through open sectors, terrain
 * cost per step, plus the Citadel siege wait when one is waiting at the end.
 */
export function planOrder(state: GameState, armyId: ArmyId, dest: HexId): Result<ArmyOrderPlan> {
  const army = state.armies[armyId];
  if (!army) return err('no such column');
  if (army.units.length === 0) return err('that column has no chassis left');
  const planned = planPath(state, armyId, dest);
  if (!planned.ok) return err(planned.error);

  let etaMs = 0;
  for (const hexId of planned.value) etaMs += stepMs(state.world, hexId);

  const target = state.world.hexes[dest];
  const defender = hostileArmyOnHex(state, dest, army.ownerId);
  const siegeMs = defender && target?.fortLevel === 3 ? FORT_RULES.siegeMs : 0;

  return ok({
    armyId,
    armyName: army.name,
    from: army.hexId,
    dest,
    path: planned.value,
    steps: planned.value.length,
    etaMs,
    siegeMs,
    contested: defender !== undefined,
  });
}

/** Verb for an order against a given hex, from the local commander's seat. */
export function orderVerb(state: GameState, hexId: HexId): string {
  const hex = state.world.hexes[hexId];
  if (!hex) return 'MOVE';
  if (hostileArmyOnHex(state, hexId, state.meId)) return 'ENGAGE';
  if (hex.ownerId && areHostile(state, hex.ownerId, state.meId)) return 'ASSAULT';
  if (!hex.ownerId) return 'CLAIM';
  return 'REDEPLOY';
}

// ─────────────────────────────────────────────────────────────────────────────
// Threat assessment (shared with staging)
// ─────────────────────────────────────────────────────────────────────────────

export type ThreatLevel = 'secure' | 'exposed' | 'contested' | 'hot';

export interface ThreatReport {
  level: ThreatLevel;
  label: string;
  note: string;
  nearestHostileHexes: number;
  hostileNeighbours: number;
  hostileForts: number;
  strongestHostileArmy: number;
}

const THREAT_META: Record<ThreatLevel, { label: string; note: string }> = {
  secure: { label: 'SECURE', note: 'No hostile signature inside the scan ring.' },
  exposed: { label: 'EXPOSED', note: 'Rival ground within a march. Expect probing.' },
  contested: { label: 'CONTESTED', note: 'Rival columns are close enough to reach this hex.' },
  hot: { label: 'HOT', note: 'Hostiles are adjacent or already on this ground.' },
};

/** How dangerous is this hex to hold, right now. */
export function threatReport(state: GameState, hexId: HexId): ThreatReport {
  const meId: PlayerId = state.meId;
  let nearest = Infinity;
  let strongest = 0;
  for (const army of Object.values(state.armies)) {
    if (army.units.length === 0) continue;
    if (!areHostile(state, army.ownerId, meId)) continue;
    const d = hexDistanceId(army.hexId, hexId);
    if (d < nearest) nearest = d;
    if (d <= 3 && army.units.length > strongest) strongest = army.units.length;
  }

  let hostileNeighbours = 0;
  let hostileForts = 0;
  for (const id of neighborIds(hexId)) {
    const hex = state.world.hexes[id];
    if (!hex?.ownerId) continue;
    if (!areHostile(state, hex.ownerId, meId)) continue;
    hostileNeighbours++;
    hostileForts = Math.max(hostileForts, hex.fortLevel);
  }

  let level: ThreatLevel = 'secure';
  if (nearest <= 1 || hostileNeighbours >= 2) level = 'hot';
  else if (nearest <= 3 || hostileNeighbours === 1) level = 'contested';
  else if (nearest <= 6 || hostileForts > 0) level = 'exposed';

  return {
    level,
    label: THREAT_META[level].label,
    note: THREAT_META[level].note,
    nearestHostileHexes: Number.isFinite(nearest) ? nearest : -1,
    hostileNeighbours,
    hostileForts,
    strongestHostileArmy: strongest,
  };
}

export const THREAT_ACCENT: Record<ThreatLevel, string> = {
  secure: 'var(--teal)',
  exposed: 'var(--gold)',
  contested: 'var(--amber)',
  hot: 'var(--crimson)',
};

// ─────────────────────────────────────────────────────────────────────────────
// Adjacency
// ─────────────────────────────────────────────────────────────────────────────

export interface AdjacencyReport {
  total: number;
  mine: number;
  allied: number;
  hostile: number;
  neutral: number;
  gas: number;
  offMap: number;
}

export function adjacencyReport(state: GameState, hexId: HexId): AdjacencyReport {
  const mineKey = factionKey(state, state.meId);
  const rep: AdjacencyReport = { total: 0, mine: 0, allied: 0, hostile: 0, neutral: 0, gas: 0, offMap: 0 };
  for (const id of neighborIds(hexId)) {
    const hex = state.world.hexes[id];
    if (!hex) {
      rep.offMap++;
      continue;
    }
    rep.total++;
    if (hex.gas) rep.gas++;
    if (!hex.ownerId) rep.neutral++;
    else if (hex.ownerId === state.meId) rep.mine++;
    else if (factionKey(state, hex.ownerId) === mineKey) rep.allied++;
    else rep.hostile++;
  }
  return rep;
}

// ─────────────────────────────────────────────────────────────────────────────
// Sheet
// ─────────────────────────────────────────────────────────────────────────────

export interface HexSheetOpts {
  backend: IBackend;
  /** Simulated-clock estimator supplied by the map screen. */
  now(): number;
  /** Hand a column to the map's order flow; `dest` pre-seeds the preview. */
  onOrderArmy(armyId: ArmyId, dest?: HexId): void;
  /** Open the radial ping menu for this hex. */
  onPingMenu(hexId: HexId): void;
  onFocusHex(hexId: HexId): void;
}

type SheetTab = 'brief' | 'works' | 'forces';

export class HexSheet {
  readonly sheet: BottomSheet;

  private readonly opts: HexSheetOpts;
  private readonly syncers: ((state: GameState) => void)[] = [];
  private readonly teardown: (() => void)[] = [];

  private current: HexId | null = null;
  private tab: SheetTab = 'brief';
  /**
   * Is the GROUND DETAIL disclosure expanded? Instance state, not DOM state, so
   * a backend push that re-renders the sheet does not collapse it under the
   * player mid-read. Deliberately NOT part of the change signature — toggling it
   * is native `<details>` behaviour and needs no re-render at all.
   */
  private detailOpen = false;
  private sig = '';
  private tabsCtl: TabsController | null = null;
  private lastState: GameState | null = null;

  constructor(opts: HexSheetOpts) {
    this.opts = opts;
    this.sheet = new BottomSheet({ class: 'sheet--hex' });
    this.sheet.onClose(() => {
      this.current = null;
      this.sig = '';
    });
  }

  get el(): HTMLElement {
    return this.sheet.el;
  }

  get hexId(): HexId | null {
    return this.current;
  }

  get isOpen(): boolean {
    return this.sheet.isOpen;
  }

  open(hexId: HexId): void {
    this.current = hexId;
    this.sig = '';
    if (this.lastState) this.render(this.lastState);
    this.sheet.open();
  }

  close(): void {
    this.sheet.close();
  }

  /** Called on every backend push. Cheap unless the hex actually changed. */
  sync(state: GameState): void {
    this.lastState = state;
    if (!this.current || !this.sheet.isOpen) return;
    const next = this.signature(state, this.current);
    if (next !== this.sig) {
      this.render(state);
      return;
    }
    for (const fn of this.syncers) fn(state);
  }

  dispose(): void {
    this.runTeardown();
    this.tabsCtl?.dispose();
    this.tabsCtl = null;
    this.sheet.dispose();
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private runTeardown(): void {
    for (const fn of this.teardown.splice(0)) {
      try {
        fn();
      } catch {
        /* ignore */
      }
    }
    this.syncers.length = 0;
  }

  private signature(state: GameState, hexId: HexId): string {
    const hex = state.world.hexes[hexId];
    if (!hex) return `${hexId}:void`;
    const sector = state.world.sectors[hex.sectorId];
    const prod = hex.production.map((o) => `${o.id}x${o.remaining}@${o.completesAt}`).join(',');
    const res = (Object.entries(hex.reserves) as [string, number][])
      .map(([k, v]) => `${k}:${v}`)
      .sort()
      .join(',');
    const armies = armiesOn(state, hexId)
      .map(
        (a) =>
          `${a.id}:${a.units.length}:${a.path.length}:${a.siege ? 1 : 0}:${
            moveCooldownRemaining(a, state.now) > 0 ? 1 : 0
          }`,
      )
      .join(',');
    const drones = Object.values(state.drones).filter((d) => d.alive && d.ownerId === state.meId).length;
    return [
      hexId,
      this.tab,
      hex.ownerId ?? '-',
      hex.fortLevel,
      hex.fortBuild?.completesAt ?? '-',
      hex.capture?.completesAt ?? '-',
      sector?.state ?? '-',
      prod,
      res,
      armies,
      drones,
      observesHex(state, hexId) ? 'eye' : 'dark',
    ].join('|');
  }

  private ctx(): PanelCtx {
    return {
      backend: this.opts.backend,
      now: () => this.opts.now(),
      refresh: () => {
        this.sig = '';
        if (this.lastState) this.render(this.lastState);
      },
      onSync: (fn) => {
        this.syncers.push(fn);
      },
      onDispose: (fn) => {
        this.teardown.push(fn);
      },
    };
  }

  private hooks(): ArmyHooks {
    return {
      onOrderArmy: (armyId) => {
        this.close();
        this.opts.onOrderArmy(armyId);
      },
      onFocusHex: (hexId) => this.opts.onFocusHex(hexId),
    };
  }

  private render(state: GameState): void {
    const hexId = this.current;
    if (!hexId) return;
    this.runTeardown();
    this.tabsCtl?.dispose();
    this.tabsCtl = null;
    this.sig = this.signature(state, hexId);

    const hex = state.world.hexes[hexId];
    const root = el('div', { class: 'hexsheet' });

    if (!hex) {
      root.appendChild(emptyState('∅', 'nothing charted at these coordinates'));
      this.sheet.setContent(root);
      return;
    }

    const ctx = this.ctx();
    const sector = state.world.sectors[hex.sectorId];
    const observed = observesHex(state, hexId);
    const relation = relationOf(state, hex);

    root.appendChild(this.header(state, hex, sector, relation));
    root.appendChild(this.statusBand(state, hex, observed, relation));

    const body = el('div', { class: 'hexsheet__body scroll' });
    root.appendChild(body);

    if (relation === 'mine') {
      const ctl = tabs(
        [
          { id: 'brief', label: 'BRIEF' },
          { id: 'works', label: 'WORKS' },
          { id: 'forces', label: 'FORCES' },
        ],
        (id) => {
          this.tab = id as SheetTab;
          this.sig = '';
          if (this.lastState) this.render(this.lastState);
        },
        this.tab,
      );
      this.tabsCtl = ctl;
      root.insertBefore(ctl.el, body);

      if (this.tab === 'works') {
        body.appendChild(fortPanel(state, hexId, ctx));
        body.appendChild(productionPanel(state, hexId, ctx));
      } else if (this.tab === 'forces') {
        body.appendChild(armiesPanel(state, hexId, ctx, this.hooks()));
        body.appendChild(garrisonPanel(state, hexId, ctx));
        const foreign = foreignArmiesPanel(state, hexId);
        if (foreign) body.appendChild(foreign);
        body.appendChild(dronePanel(state, hexId, ctx, this.hooks()));
      } else {
        body.appendChild(this.brief(state, hex));
        const foreign = foreignArmiesPanel(state, hexId);
        if (foreign) body.appendChild(foreign);
        body.appendChild(this.reachList(state, hexId));
      }
    } else {
      body.appendChild(this.brief(state, hex));
      if (observed) {
        const foreign = foreignArmiesPanel(state, hexId);
        if (foreign) body.appendChild(foreign);
        else body.appendChild(note('NO COLUMN ON THIS GROUND'));
      } else {
        body.appendChild(intelPanel(state, hexId, ctx));
      }
      body.appendChild(this.reachList(state, hexId));
    }

    root.appendChild(this.actions(state, hexId));
    this.sheet.setContent(root);
    for (const fn of this.syncers) fn(state);
  }

  // ── sections ──────────────────────────────────────────────────────────────

  private header(state: GameState, hex: Hex, sector: Sector | undefined, relation: Relation): HTMLElement {
    const meta = TERRAIN_META[hex.terrain];
    const head = el('div', {
      class: `hexsheet__head hexsheet__head--${relation}`,
      style: `--accent:${terrainAccent(hex.terrain)}`,
    });

    const art = el('div', { class: 'hexsheet__art', aria: { hidden: 'true' } });
    art.appendChild(svgEl(terrainArt(hex.terrain)));
    head.appendChild(art);
    head.appendChild(el('div', { class: 'hexsheet__scrim', aria: { hidden: 'true' } }));

    const titles = el(
      'div',
      { class: 'hexsheet__titles' },
      el('div', { class: 'hexsheet__coord mono', text: `Q${hex.q} · R${hex.r}` }),
      el('div', { class: 'hexsheet__terrain display', text: meta.label }),
      el('div', { class: 'hexsheet__sector mono', text: sector?.designation ?? 'UNCHARTED' }),
    );
    head.appendChild(titles);

    const flags = el('div', { class: 'hexsheet__flags' });
    if (hex.gas) flags.appendChild(badge('GAS', 'ok'));
    if (sector?.state === 'closing' && sector.closesAt !== undefined) {
      const cd = countdown(sector.closesAt, { getNow: () => this.opts.now(), compact: true, doneText: 'GONE' });
      this.teardown.push(() => cd.stop());
      const wrap = el('span', { class: 'hexsheet__flag hexsheet__flag--bad' }, el('b', { text: 'SHUTDOWN' }), cd.el);
      flags.appendChild(wrap);
    } else if (sector && sector.state !== 'active') {
      flags.appendChild(badge('SECTOR LOCKED', 'bad'));
    }
    if (hex.capture) {
      const cd = countdown(hex.capture.completesAt, {
        getNow: () => this.opts.now(),
        compact: true,
        doneText: 'FLIPPING',
      });
      this.teardown.push(() => cd.stop());
      const who = state.players[hex.capture.playerId]?.name ?? 'UNKNOWN';
      flags.appendChild(
        el('span', { class: 'hexsheet__flag hexsheet__flag--hot' }, el('b', { text: `CAPTURE · ${who}` }), cd.el),
      );
    }
    if (hex.fortLevel > 0) flags.appendChild(badge(fortTag(hex.fortLevel), 'gold'));
    head.appendChild(flags);

    return head;
  }

  private statusBand(state: GameState, hex: Hex, observed: boolean, relation: Relation): HTMLElement {
    const owner = hex.ownerId ? state.players[hex.ownerId] : undefined;
    const guild = owner?.guildId ? state.guilds[owner.guildId] : undefined;
    const y = hexYield(state, hex);

    return el(
      'div',
      { class: 'hexsheet__band' },
      el(
        'div',
        { class: `hexsheet__holder hexsheet__holder--${relation}` },
        el('span', { class: 'hexsheet__holder-k', text: 'HOLDER' }),
        el('span', {
          class: 'hexsheet__holder-v truncate',
          text: owner ? owner.name : 'UNCLAIMED GROUND',
        }),
        guild ? badge(`[${guild.tag}]`, relation === 'hostile' ? 'hot' : 'ok') : badge('NEUTRAL'),
      ),
      el(
        'div',
        { class: 'hexsheet__meta' },
        el('span', { class: 'mono', text: `${fmtNum(y.m)} M/TICK` }),
        hex.gas ? el('span', { class: 'mono ok-t', text: `${fmtNum(y.g)} G/TICK` }) : null,
        el('span', { class: 'mono dim-2', text: observed ? 'LIVE FEED' : 'NO EYES ON' }),
      ),
    );
  }

  /**
   * The dossier, rewritten to fit a phone.
   *
   * This used to open with a flavour paragraph, five stat rows, a six-cell
   * adjacency grid and a three-line threat block — before REACH and the action
   * bar had said anything. On a 390×844 screen that is the whole display for one
   * tap on one tile, and the map you are reading disappears behind it.
   *
   * So the default answers only the three questions a tap actually asks — how
   * dangerous is it, what does it pay, how long to take it — and everything else
   * is demoted into GROUND DETAIL rather than deleted. Nothing was cut from the
   * sheet; it is one tap further away.
   */
  private brief(state: GameState, hex: Hex): HTMLElement {
    const meta = TERRAIN_META[hex.terrain];
    const adj = adjacencyReport(state, hex.id);
    const threat = threatReport(state, hex.id);
    const y = hexYield(state, hex);

    const wrap = el('div', { class: 'brief' });

    // Can I hold this? One line, colour-coded, no prose.
    wrap.appendChild(
      el(
        'div',
        {
          class: `threat threat--compact threat--${threat.level}`,
          style: `--accent:${THREAT_ACCENT[threat.level]}`,
        },
        el('span', { class: 'threat__label display', text: threat.label }),
        el('span', { class: 'spacer' }),
        el('span', {
          class: 'threat__dist mono',
          text: threat.nearestHostileHexes < 0 ? 'NO CONTACT' : `NEAREST ${threat.nearestHostileHexes} HEX`,
        }),
      ),
    );

    // What does it pay, and what does it cost to take? Three figures, one strip.
    wrap.appendChild(
      el(
        'div',
        { class: 'gfacts' },
        fact(y.g > 0 ? `${fmtNum(y.m)}M · ${fmtNum(y.g)}G` : `${fmtNum(y.m)}M`, 'PER TICK', 'var(--teal)'),
        fact(fmtDuration(stepMs(state.world, hex.id)), 'STEP', 'var(--cyan)'),
        fact(fmtDuration(captureDurationMs(hex)), 'CAPTURE', 'var(--gold)'),
      ),
    );

    // ── everything else, one tap down ───────────────────────────────────────
    const detail = el('details', {
      class: 'hexdetail',
      attrs: { open: this.detailOpen },
    });
    detail.appendChild(
      el(
        'summary',
        { class: 'hexdetail__sum mono' },
        el('span', { class: 'grow', text: 'GROUND DETAIL' }),
        el('span', { class: 'hexdetail__chev', aria: { hidden: 'true' } }),
      ),
    );
    detail.addEventListener('toggle', () => {
      this.detailOpen = detail.open;
    });

    const inner = el('div', { class: 'hexdetail__body' });
    inner.appendChild(el('p', { class: 'brief__blurb', text: meta.blurb }));

    inner.appendChild(statRow('MOVE COST', `×${MAP.moveCostByTerrain[hex.terrain].toFixed(2)}`));
    inner.appendChild(
      statRow('EMPLACEMENT', fortTag(hex.fortLevel), {
        accent: hex.fortLevel > 0 ? 'var(--gold)' : undefined,
      }),
    );

    inner.appendChild(sectionHeader('APPROACHES'));
    const lanes = el('div', { class: 'lanes' });
    const laneDefs: { k: string; v: number; tone: string }[] = [
      { k: 'YOURS', v: adj.mine, tone: 'var(--cyan)' },
      { k: 'ALLIED', v: adj.allied, tone: 'var(--teal)' },
      { k: 'HOSTILE', v: adj.hostile, tone: 'var(--crimson)' },
      { k: 'OPEN', v: adj.neutral, tone: 'var(--neutral)' },
      { k: 'GAS', v: adj.gas, tone: 'var(--lime)' },
      { k: 'EDGE', v: adj.offMap, tone: 'var(--ink-4)' },
    ];
    for (const lane of laneDefs) {
      lanes.appendChild(
        el(
          'div',
          { class: 'lanes__cell', style: `--accent:${lane.tone}` },
          el('span', { class: 'lanes__v mono', text: String(lane.v) }),
          el('span', { class: 'lanes__k', text: lane.k }),
        ),
      );
    }
    inner.appendChild(lanes);

    inner.appendChild(sectionHeader('THREAT'));
    inner.appendChild(el('div', { class: 'threat__note', text: threat.note }));
    inner.appendChild(
      el('div', {
        class: 'threat__nums mono',
        text: `HOSTILE BORDERS ${threat.hostileNeighbours} · RIVAL WORKS L${threat.hostileForts} · HEAVIEST COLUMN ${threat.strongestHostileArmy}`,
      }),
    );

    detail.appendChild(inner);
    wrap.appendChild(detail);

    return wrap;
  }

  /** Which of your columns can reach this hex, and how long it takes them. */
  private reachList(state: GameState, hexId: HexId): HTMLElement {
    const wrap = el('div', { class: 'reach' });
    const verb = orderVerb(state, hexId);
    wrap.appendChild(sectionHeader('REACH'));

    const mine: Army[] = Object.values(state.armies)
      .filter((a) => a.ownerId === state.meId && a.units.length > 0 && a.hexId !== hexId)
      .sort((a, b) => hexDistanceId(a.hexId, hexId) - hexDistanceId(b.hexId, hexId));

    if (mine.length === 0) {
      wrap.appendChild(note('NO COLUMN OF YOURS IS FREE TO MARCH'));
      return wrap;
    }

    let listed = 0;
    for (const army of mine) {
      if (listed >= 3) break;
      const plan = planOrder(state, army.id, hexId);
      if (!plan.ok) continue;
      listed++;
      const p = plan.value;
      const total = p.etaMs + p.siegeMs;
      const cooling = moveCooldownRemaining(army, this.opts.now());

      const act = button(verb, {
        variant: 'primary',
        small: true,
        disabled: cooling > 0,
        onClick: () => {
          haptic(12);
          this.close();
          this.opts.onOrderArmy(army.id, hexId);
        },
      });

      const info = el(
        'div',
        { class: 'grow' },
        el('div', { class: 'reach__name display truncate', text: army.name }),
        el('div', {
          class: 'reach__sub mono',
          text: `${p.steps} HEX · ${fmtDuration(total)}${p.siegeMs > 0 ? ' (INC. SIEGE)' : ''}`,
        }),
      );

      const row = el('div', { class: `reach__row${cooling > 0 ? ' reach__row--cool' : ''}` }, info, act);

      // A column that has only just taken ground cannot be sent on. Say so, and
      // arm the control the instant it is free rather than on the next push —
      // these rows are not in the sheet's change signature.
      if (cooling > 0 && army.moveReadyAt !== undefined) {
        const cd = countdown(army.moveReadyAt, {
          getNow: () => this.opts.now(),
          prefix: 'REGROUPING · READY IN',
          doneText: 'READY',
          onDone: () => {
            act.disabled = false;
            row.classList.remove('reach__row--cool');
          },
        });
        this.teardown.push(() => cd.stop());
        info.appendChild(el('div', { class: 'reach__cool' }, cd.el));
      }

      wrap.appendChild(row);
    }

    if (listed === 0) {
      wrap.appendChild(note('NO ROUTE THROUGH OPEN SECTORS'));
    }
    return wrap;
  }

  private actions(state: GameState, hexId: HexId): HTMLElement {
    const bar = el('div', { class: 'hexsheet__acts' });
    bar.appendChild(
      button('PING / MARK', {
        variant: 'ghost',
        small: true,
        onClick: () => {
          this.close();
          this.opts.onPingMenu(hexId);
        },
      }),
    );
    bar.appendChild(
      button('CENTRE', {
        variant: 'quiet',
        small: true,
        onClick: () => this.opts.onFocusHex(hexId),
      }),
    );
    const mark = state.marks.find((m) => m.hexId === hexId && m.guildId === factionKey(state, state.meId));
    if (mark) {
      bar.appendChild(
        button('CLEAR MARK', {
          variant: 'quiet',
          small: true,
          onClick: () => {
            void (async () => {
              const res = await this.opts.backend.removeMark(mark.id);
              if (!res.ok) toast({ title: 'ORDER REFUSED', body: res.error, kind: 'bad' });
              else toast({ title: 'MARK CLEARED', kind: 'ok' });
            })();
          },
        }),
      );
    }
    // No CLOSE button. The sheet already closes three other ways — scrim tap,
    // the grab handle, and a downward drag — and a fourth was costing a third of
    // the action row's width, which is what made the real actions wrap.
    return bar;
  }
}

// ─────────────────────────────────────────────────────────────────────────────

/**
 * A one-line statement of absence.
 *
 * `emptyState` renders a 128px icon-and-caption block — more furniture than the
 * entire ground dossier next to it, spent on saying "there is nothing here".
 * Fine on a full screen, absurd inside a sheet this size.
 */
function note(text: string): HTMLElement {
  return el(
    'div',
    { class: 'hexnote mono' },
    el('i', { aria: { hidden: 'true' } }),
    el('span', { text }),
  );
}

/** One figure in the facts strip: the number loud, its label quiet under it. */
function fact(value: string, label: string, tone: string): HTMLElement {
  return el(
    'div',
    { class: 'gfacts__cell', style: `--accent:${tone}` },
    el('span', { class: 'gfacts__v mono', text: value }),
    el('span', { class: 'gfacts__k', text: label }),
  );
}

type Relation = 'mine' | 'allied' | 'hostile' | 'neutral';

function relationOf(state: GameState, hex: Hex): Relation {
  if (!hex.ownerId) return 'neutral';
  if (hex.ownerId === state.meId) return 'mine';
  return factionKey(state, hex.ownerId) === factionKey(state, state.meId) ? 'allied' : 'hostile';
}

/** Convenience for other screens: a compact hex identity plate. */
export function hexPlate(hex: Hex, sector?: Sector): HTMLElement {
  const meta = TERRAIN_META[hex.terrain];
  const node = el(
    'div',
    { class: 'hexplate', style: `--accent:${terrainAccent(hex.terrain)}` },
    el('span', { class: 'hexplate__id mono', text: hex.id }),
    el('span', { class: 'hexplate__terr', text: meta.label }),
  );
  if (sector) node.appendChild(el('span', { class: 'hexplate__sec mono', text: sector.name }));
  if (hex.gas) node.appendChild(badge('GAS', 'ok'));
  return node;
}
