/**
 * Bottom sheet with a real drag-to-dismiss gesture.
 *
 * The sheet owns a fixed-position root that must be appended somewhere near the
 * top of the shell (usually `document.body` or the screen root). It is inert
 * until `open()`.
 */
import { el, clear, haptic } from '../dom';

export interface BottomSheetOpts {
  /** Px of the panel to leave visible when closed (0 = fully hidden). */
  peek?: number;
  /** Extra class on the root. */
  class?: string;
  /** Tapping the scrim closes the sheet. Default true. */
  dismissable?: boolean;
}

const DISMISS_PX = 88;
const DISMISS_VELOCITY = 0.55; // px/ms

export class BottomSheet {
  readonly el: HTMLElement;

  private readonly scrim: HTMLElement;
  private readonly panel: HTMLElement;
  private readonly grab: HTMLElement;
  private readonly body: HTMLElement;
  private readonly closeCbs: (() => void)[] = [];
  private readonly peek: number;

  private open_ = false;
  private dragging = false;
  private pointerId = -1;
  private startY = 0;
  private startT = 0;
  private lastY = 0;
  private lastT = 0;
  private dy = 0;

  constructor(opts: BottomSheetOpts = {}) {
    this.peek = Math.max(0, opts.peek ?? 0);

    this.scrim = el('div', { class: 'sheet__scrim' });
    this.grab = el('div', { class: 'sheet__grab', aria: { hidden: 'true' } }, el('i'));
    this.body = el('div', { class: 'sheet__body' });
    this.panel = el('div', { class: 'sheet__panel' }, this.grab, this.body);
    const rootClasses = ['sheet'];
    if (this.peek > 0) rootClasses.push('sheet--peeking');
    if (opts.class) rootClasses.push(opts.class);
    this.el = el(
      'div',
      {
        class: rootClasses.join(' '),
        attrs: { role: 'dialog' },
        aria: { modal: 'false', hidden: 'true' },
      },
      this.scrim,
      this.panel,
    );

    if (opts.dismissable !== false) {
      this.scrim.addEventListener('pointerdown', (ev: PointerEvent) => {
        ev.preventDefault();
        this.close();
      });
    }

    this.grab.addEventListener('pointerdown', this.onDown);
    this.grab.addEventListener('pointermove', this.onMove);
    this.grab.addEventListener('pointerup', this.onUp);
    this.grab.addEventListener('pointercancel', this.onUp);

    this.applyPeek();
  }

  get isOpen(): boolean {
    return this.open_;
  }

  /** Direct access to the scrollable content region (for measuring / scrolling). */
  get content(): HTMLElement {
    return this.body;
  }

  setContent(node: Node): void {
    clear(this.body);
    this.body.appendChild(node);
    this.body.scrollTop = 0;
  }

  open(): void {
    if (this.open_) return;
    this.open_ = true;
    this.panel.style.transform = '';
    this.el.classList.add('sheet--open');
    this.el.setAttribute('aria-hidden', 'false');
    haptic(10);
  }

  close(): void {
    if (!this.open_) return;
    this.open_ = false;
    this.el.classList.remove('sheet--open', 'sheet--dragging');
    this.el.setAttribute('aria-hidden', 'true');
    this.applyPeek();
    for (const cb of this.closeCbs) cb();
  }

  toggle(): void {
    if (this.open_) this.close();
    else this.open();
  }

  onClose(cb: () => void): void {
    this.closeCbs.push(cb);
  }

  dispose(): void {
    this.closeCbs.length = 0;
    this.el.remove();
  }

  // ── drag ──────────────────────────────────────────────────────────────────

  private applyPeek(): void {
    this.panel.style.transform = this.peek > 0 ? `translate3d(0, calc(100% - ${this.peek}px), 0)` : '';
  }

  private onDown = (ev: PointerEvent): void => {
    if (!this.open_ || this.dragging) return;
    this.dragging = true;
    this.pointerId = ev.pointerId;
    this.startY = ev.clientY;
    this.lastY = ev.clientY;
    this.startT = performance.now();
    this.lastT = this.startT;
    this.dy = 0;
    this.el.classList.add('sheet--dragging');
    this.grab.setPointerCapture(ev.pointerId);
    ev.preventDefault();
  };

  private onMove = (ev: PointerEvent): void => {
    if (!this.dragging || ev.pointerId !== this.pointerId) return;
    const raw = ev.clientY - this.startY;
    // Rubber-band upward drags so the sheet never floats off the bottom edge.
    this.dy = raw >= 0 ? raw : raw * 0.24;
    this.lastY = ev.clientY;
    this.lastT = performance.now();
    this.panel.style.transform = `translate3d(0, ${this.dy.toFixed(1)}px, 0)`;
    this.scrim.style.opacity = String(Math.max(0, 1 - Math.max(0, this.dy) / 420));
    ev.preventDefault();
  };

  private onUp = (ev: PointerEvent): void => {
    if (!this.dragging || ev.pointerId !== this.pointerId) return;
    this.dragging = false;
    this.pointerId = -1;
    this.el.classList.remove('sheet--dragging');
    this.scrim.style.opacity = '';
    if (this.grab.hasPointerCapture(ev.pointerId)) this.grab.releasePointerCapture(ev.pointerId);

    const dt = Math.max(1, this.lastT - this.startT);
    const velocity = (this.lastY - this.startY) / dt;

    if (this.dy > DISMISS_PX || velocity > DISMISS_VELOCITY) {
      this.panel.style.transform = '';
      this.close();
    } else {
      this.panel.style.transform = '';
    }
    this.dy = 0;
  };
}
